// Part 5 題庫（契約 §3.1、§5 Part5Question；V-P5-01～07）。全部原創（AC-23-04）。
// CT-19：preposition_collocation 50、part_of_speech 50；CT-20：context_vocabulary 50、connector 50，並以題型交錯排序、重編 id p5-001～p5-200。
// 格式：每題一行（JSON.stringify，鍵順序依 data-schema.ts 宣告順序），陣列順序即出題順序。
window.PART5_QUESTION_BANK = [
{"id":"p5-001","type":"preposition_collocation","sentence":"The marketing team is responsible _____ launching the new product line next quarter.","options":["for","with","to","at"],"correctIndex":0,"explanation":{"coreStrategy":"be responsible for + 名詞／V-ing 是固定搭配，表示「負責某事」；空格後接動名詞 launching，選 for。","structure":"S: The marketing team / V: is responsible for / O: launching the new product line / 修飾語: next quarter"},"source":"ORIGINAL"},
{"id":"p5-002","type":"part_of_speech","sentence":"The new manager made a _____ to extend the store's opening hours.","options":["decide","decisive","decision","decisively"],"correctIndex":2,"explanation":{"coreStrategy":"冠詞 a 後面需要名詞，make a decision 是固定搭配；decide 是動詞、decisive 是形容詞、decisively 是副詞。","structure":"S: The new manager / V: made / O: a decision / 修飾語: to extend the store's opening hours（修飾 decision）"},"source":"ORIGINAL"},
{"id":"p5-003","type":"context_vocabulary","sentence":"Due to a scheduling conflict, the board meeting has been _____ until next Thursday.","options":["postponed","estimated","reminded","attended"],"correctIndex":0,"explanation":{"coreStrategy":"空格後的 until next Thursday 是關鍵線索：會議因時程衝突被「延到」下週四，postpone 意為「延期」。reminded（提醒）、attended（出席）、estimated（估計）都不能和 until 搭配表示時間延後。","structure":"S: the board meeting / V: has been postponed / O: 無（被動語態）/ 修飾語: Due to a scheduling conflict；until next Thursday"},"source":"ORIGINAL"},
{"id":"p5-004","type":"connector","sentence":"_____ the heavy rain, the outdoor concert went ahead as scheduled.","options":["Because of","However","Despite","Although"],"correctIndex":2,"explanation":{"coreStrategy":"空格後是名詞片語 the heavy rain，需要介系詞；前後語意相反（下大雨但照常舉行），所以用表讓步的 Despite。Although 是連接詞，後面要接子句；Because of 表原因，語意相反；However 是副詞，不能直接接名詞。","structure":"S: the outdoor concert / V: went ahead / O: 無（不及物動詞）/ 修飾語: Despite the heavy rain；as scheduled"},"source":"ORIGINAL"},
{"id":"p5-005","type":"preposition_collocation","sentence":"Ms. Tanaka has been in charge _____ the Osaka branch since last April.","options":["for","with","of","on"],"correctIndex":2,"explanation":{"coreStrategy":"in charge of 是固定片語，意為「負責管理」；空格前的 in charge 是關鍵線索，只能接 of。","structure":"S: Ms. Tanaka / V: has been in charge of / O: the Osaka branch / 修飾語: since last April"},"source":"ORIGINAL"},
{"id":"p5-006","type":"part_of_speech","sentence":"Ms. Grant responded _____ to every customer complaint she received.","options":["promptly","prompt","prompted","promptness"],"correctIndex":0,"explanation":{"coreStrategy":"空格修飾不及物動詞 responded，需要副詞；-ly 結尾的 promptly 表示「迅速地」。","structure":"S: Ms. Grant / V: responded / O: 無（不及物動詞）/ 修飾語: promptly；to every customer complaint (that) she received"},"source":"ORIGINAL"},
{"id":"p5-007","type":"context_vocabulary","sentence":"Please keep your receipt as _____ of purchase in case you need to return the item.","options":["proof","purpose","profit","prize"],"correctIndex":0,"explanation":{"coreStrategy":"收據的用途是證明買過商品，proof of purchase 意為「購買證明」，與後半句 in case you need to return the item（萬一要退貨）呼應。profit（利潤）、prize（獎品）、purpose（目的）語意都不通。","structure":"S: （you，祈使句省略）/ V: Please keep / O: your receipt / 修飾語: as proof of purchase；in case you need to return the item（副詞子句）"},"source":"ORIGINAL"},
{"id":"p5-008","type":"connector","sentence":"_____ the weather was cold, many people attended the outdoor festival.","options":["Although","In spite of","Due to","Despite"],"correctIndex":0,"explanation":{"coreStrategy":"空格後是完整子句 the weather was cold（有主詞和動詞），需要連接詞；天冷卻很多人參加，是讓步關係，選 Although。Despite、In spite of、Due to 都是介系詞，只能接名詞片語。","structure":"S: many people / V: attended / O: the outdoor festival / 修飾語: Although the weather was cold（讓步子句）"},"source":"ORIGINAL"},
{"id":"p5-009","type":"preposition_collocation","sentence":"Applicants who are interested _____ the position should submit a résumé by Friday.","options":["on","in","at","about"],"correctIndex":1,"explanation":{"coreStrategy":"be interested in 表示「對……有興趣」，是常見的形容詞＋介系詞搭配。","structure":"S: Applicants (who are interested in the position) / V: should submit / O: a résumé / 修飾語: who are interested in the position（關係子句）；by Friday"},"source":"ORIGINAL"},
{"id":"p5-010","type":"part_of_speech","sentence":"The company's _____ in the Asian market has exceeded expectations.","options":["expand","expansive","expansion","expanded"],"correctIndex":2,"explanation":{"coreStrategy":"所有格 The company's 後面要接名詞，且整個名詞片語當主詞、搭配單數動詞 has；-sion 結尾的 expansion 是名詞。","structure":"S: The company's expansion / V: has exceeded / O: expectations / 修飾語: in the Asian market"},"source":"ORIGINAL"},
{"id":"p5-011","type":"context_vocabulary","sentence":"The new assembly line has significantly increased the factory's production _____.","options":["tenant","audience","souvenir","capacity"],"correctIndex":3,"explanation":{"coreStrategy":"新生產線提高的是工廠的「產能」，production capacity 是常見名詞搭配。audience（觀眾）、tenant（房客）、souvenir（紀念品）都無法被生產線提高。","structure":"S: The new assembly line / V: has increased / O: the factory's production capacity / 修飾語: significantly"},"source":"ORIGINAL"},
{"id":"p5-012","type":"connector","sentence":"The flight was delayed _____ a mechanical problem with the engine.","options":["therefore","because","because of","although"],"correctIndex":2,"explanation":{"coreStrategy":"空格後是名詞片語 a mechanical problem，需要介系詞；機械故障是延誤的原因，選 because of。because、although 是連接詞，後面要接子句；therefore 是副詞，不能接名詞。","structure":"S: The flight / V: was delayed / O: 無（被動語態）/ 修飾語: because of a mechanical problem with the engine"},"source":"ORIGINAL"},
{"id":"p5-013","type":"preposition_collocation","sentence":"The final price will depend _____ the number of units ordered.","options":["at","with","to","on"],"correctIndex":3,"explanation":{"coreStrategy":"depend on 表示「取決於」；動詞 depend 後面固定接 on（或 upon），其他介系詞都不成立。","structure":"S: The final price / V: will depend on / O: the number of units / 修飾語: ordered（過去分詞修飾 units）"},"source":"ORIGINAL"},
{"id":"p5-014","type":"part_of_speech","sentence":"Participants are advised to read the instructions _____ before assembling the shelf.","options":["carefully","careful","care","carefulness"],"correctIndex":0,"explanation":{"coreStrategy":"「read the instructions」已是完整的動詞＋受詞，空格修飾動作 read，需要副詞 carefully。","structure":"S: Participants / V: are advised / O: to read the instructions / 修飾語: carefully；before assembling the shelf"},"source":"ORIGINAL"},
{"id":"p5-015","type":"context_vocabulary","sentence":"All visitors must _____ at the front desk before entering the laboratory.","options":["retire","resign","register","recover"],"correctIndex":2,"explanation":{"coreStrategy":"訪客進實驗室前要在櫃檯「登記」，register 為不及物用法，後接地點 at the front desk。resign（辭職）、recover（康復）、retire（退休）都不符合訪客的情境。","structure":"S: All visitors / V: must register / O: 無（不及物動詞）/ 修飾語: at the front desk；before entering the laboratory"},"source":"ORIGINAL"},
{"id":"p5-016","type":"connector","sentence":"The shipment arrived late _____ the truck driver took the wrong route.","options":["however","because of","despite","because"],"correctIndex":3,"explanation":{"coreStrategy":"空格後是子句 the truck driver took the wrong route，需要連接詞；走錯路是晚到的原因，選 because。because of、despite 是介系詞，不能接子句；however 是副詞，不能連接兩個子句。","structure":"S: The shipment / V: arrived / O: 無（不及物動詞）/ 修飾語: late；because the truck driver took the wrong route（原因子句）"},"source":"ORIGINAL"},
{"id":"p5-017","type":"preposition_collocation","sentence":"Our new software is compatible _____ most operating systems currently on the market.","options":["to","with","for","of"],"correctIndex":1,"explanation":{"coreStrategy":"be compatible with 表示「與……相容」；看到 compatible 直接聯想 with。","structure":"S: Our new software / V: is compatible with / O: most operating systems / 修飾語: currently on the market"},"source":"ORIGINAL"},
{"id":"p5-018","type":"part_of_speech","sentence":"The hotel offers _____ rates for groups of ten or more.","options":["compete","competitive","competitively","competition"],"correctIndex":1,"explanation":{"coreStrategy":"空格在名詞 rates 前面，需要形容詞修飾；competitive rates 表示「有競爭力的價格」。","structure":"S: The hotel / V: offers / O: competitive rates / 修飾語: for groups of ten or more"},"source":"ORIGINAL"},
{"id":"p5-019","type":"context_vocabulary","sentence":"The hotel offers _____ shuttle service to and from the airport for all guests.","options":["complementary","complimentary","contagious","confidential"],"correctIndex":1,"explanation":{"coreStrategy":"飯店為所有房客提供的接駁車通常是「免費的」，complimentary 意為「贈送的、免費的」。complementary（互補的）拼字只差一個字母，是常見陷阱；confidential（機密的）、contagious（傳染性的）語意不通。","structure":"S: The hotel / V: offers / O: complimentary shuttle service / 修飾語: to and from the airport；for all guests"},"source":"ORIGINAL"},
{"id":"p5-020","type":"connector","sentence":"The new laptop is expensive; _____, it has become our best-selling model.","options":["therefore","because","nevertheless","despite"],"correctIndex":2,"explanation":{"coreStrategy":"分號後加逗號的位置需要連接副詞；「價格貴」與「成為最暢銷機種」語意相反，選表讓步的 nevertheless（儘管如此）。therefore 表因果，語意不通；because 是連接詞、despite 是介系詞，都不能放在分號後加逗號的位置。","structure":"S: it / V: has become / O: 無（補語 our best-selling model）/ 修飾語: nevertheless；（前一子句 The new laptop is expensive）"},"source":"ORIGINAL"},
{"id":"p5-021","type":"preposition_collocation","sentence":"Please refer _____ the attached schedule for the dates of the training sessions.","options":["to","at","on","with"],"correctIndex":0,"explanation":{"coreStrategy":"refer to 表示「參閱、參考」，是公告與電子郵件的固定用語；空格後接文件名稱，選 to。","structure":"S: （you，祈使句省略）/ V: Please refer to / O: the attached schedule / 修飾語: for the dates of the training sessions"},"source":"ORIGINAL"},
{"id":"p5-022","type":"part_of_speech","sentence":"Our sales figures increased _____ after the advertising campaign was launched.","options":["significantly","significant","significance","signify"],"correctIndex":0,"explanation":{"coreStrategy":"空格修飾不及物動詞 increased，需要副詞；significantly 表示「大幅地」。","structure":"S: Our sales figures / V: increased / O: 無（不及物動詞）/ 修飾語: significantly；after the advertising campaign was launched"},"source":"ORIGINAL"},
{"id":"p5-023","type":"context_vocabulary","sentence":"Ms. Rivera was _____ to regional manager after five years of outstanding performance.","options":["produced","promoted","provided","prohibited"],"correctIndex":1,"explanation":{"coreStrategy":"was ___ to + 職稱，再加上 outstanding performance（表現傑出），可知是「升職」，be promoted to 意為「被拔擢為」。provided（提供）、produced（生產）、prohibited（禁止）語意都不通。","structure":"S: Ms. Rivera / V: was promoted / O: 無（被動語態）/ 修飾語: to regional manager；after five years of outstanding performance"},"source":"ORIGINAL"},
{"id":"p5-024","type":"connector","sentence":"The supplier raised its prices by 20 percent; _____, we have started looking for a new vendor.","options":["however","despite","although","therefore"],"correctIndex":3,"explanation":{"coreStrategy":"分號後加逗號的位置需要連接副詞；供應商漲價是因，找新廠商是果，選 therefore（因此）。however 表轉折，語意不通；although 是連接詞、despite 是介系詞，不能放在這個位置。","structure":"S: we / V: have started / O: looking for a new vendor / 修飾語: therefore；（前一子句 The supplier raised its prices by 20 percent）"},"source":"ORIGINAL"},
{"id":"p5-025","type":"preposition_collocation","sentence":"The company's success can be attributed _____ its commitment to customer service.","options":["for","with","to","by"],"correctIndex":2,"explanation":{"coreStrategy":"attribute A to B 表示「把 A 歸因於 B」；被動 A be attributed to B，空格後是原因，選 to。","structure":"S: The company's success / V: can be attributed to / O: its commitment / 修飾語: to customer service（修飾 commitment）"},"source":"ORIGINAL"},
{"id":"p5-026","type":"part_of_speech","sentence":"The _____ of the new warehouse will take approximately eight months.","options":["construct","constructive","construction","constructively"],"correctIndex":2,"explanation":{"coreStrategy":"the _____ of 的結構中，空格必須是名詞；-tion 結尾的 construction 是名詞。","structure":"S: The construction of the new warehouse / V: will take / O: approximately eight months / 修飾語: of the new warehouse（修飾 construction）"},"source":"ORIGINAL"},
{"id":"p5-027","type":"context_vocabulary","sentence":"The warranty _____ all repairs for two years from the date of purchase.","options":["discovers","uncovers","recovers","covers"],"correctIndex":3,"explanation":{"coreStrategy":"保固「涵蓋、支付」維修費用，cover 在保險、保固情境中意為「承保、給付」。recovers（恢復）、discovers（發現）、uncovers（揭露）都是同字根的誘答，語意不通。","structure":"S: The warranty / V: covers / O: all repairs / 修飾語: for two years from the date of purchase"},"source":"ORIGINAL"},
{"id":"p5-028","type":"connector","sentence":"_____ of the road construction, employees are advised to leave home earlier than usual.","options":["Although","Due","Since","Because"],"correctIndex":3,"explanation":{"coreStrategy":"空格後緊接 of，只有 Because 能組成介系詞片語 because of，表示原因（因為道路施工所以提早出門）。Since、Although 不能接 of；due 要搭配 to 成為 due to，due of 不成立。","structure":"S: employees / V: are advised / O: 無（被動語態）/ 修飾語: Because of the road construction；to leave home earlier than usual"},"source":"ORIGINAL"},
{"id":"p5-029","type":"preposition_collocation","sentence":"Several staff members have objected _____ the proposed changes to the vacation policy.","options":["at","to","with","for"],"correctIndex":1,"explanation":{"coreStrategy":"object to 表示「反對」；注意這裡的 to 是介系詞，後面接名詞（the proposed changes）。","structure":"S: Several staff members / V: have objected to / O: the proposed changes / 修飾語: to the vacation policy（修飾 changes）"},"source":"ORIGINAL"},
{"id":"p5-030","type":"part_of_speech","sentence":"Mr. Hayashi is an _____ engineer with over fifteen years of experience.","options":["experience","experienced","experiencing","experientially"],"correctIndex":1,"explanation":{"coreStrategy":"冠詞 an 與名詞 engineer 之間要放形容詞；experienced 表示「有經驗的」，用來形容人。","structure":"S: Mr. Hayashi / V: is / O: 無（補語 an experienced engineer）/ 修飾語: with over fifteen years of experience"},"source":"ORIGINAL"},
{"id":"p5-031","type":"context_vocabulary","sentence":"Our customer service representatives are _____ 24 hours a day, seven days a week.","options":["available","valuable","affordable","durable"],"correctIndex":0,"explanation":{"coreStrategy":"24 hours a day, seven days a week 表示全天候，客服人員「可以提供服務、聯絡得到」，用 available。valuable（有價值的）、affordable（負擔得起的）、durable（耐用的）不用來描述服務時間。","structure":"S: Our customer service representatives / V: are / O: 無（補語 available）/ 修飾語: 24 hours a day, seven days a week"},"source":"ORIGINAL"},
{"id":"p5-032","type":"connector","sentence":"_____ our sales team exceeded its target, everyone received a bonus.","options":["Although","Because","Despite","Therefore"],"correctIndex":1,"explanation":{"coreStrategy":"空格後是子句，需要連接詞；業績達標是領到獎金的原因，選 Because。Although 雖是連接詞，但表讓步，語意相反；Despite 是介系詞，不能接子句；Therefore 是副詞，不能引導從屬子句。","structure":"S: everyone / V: received / O: a bonus / 修飾語: Because our sales team exceeded its target（原因子句）"},"source":"ORIGINAL"},
{"id":"p5-033","type":"preposition_collocation","sentence":"The board of directors finally agreed _____ the terms of the merger.","options":["at","by","to","from"],"correctIndex":2,"explanation":{"coreStrategy":"agree to + 提議／條件，表示「同意（條款、計畫）」；at、by、from 都不和 agree 搭配。","structure":"S: The board of directors / V: agreed to / O: the terms / 修飾語: finally；of the merger（修飾 terms）"},"source":"ORIGINAL"},
{"id":"p5-034","type":"part_of_speech","sentence":"The employee handbook explains the company's policies in a clear and _____ manner.","options":["concisely","concision","concise","conciseness"],"correctIndex":2,"explanation":{"coreStrategy":"對等連接詞 and 連接兩個同詞性的字；clear 是形容詞，共同修飾名詞 manner，所以選形容詞 concise。","structure":"S: The employee handbook / V: explains / O: the company's policies / 修飾語: in a clear and concise manner"},"source":"ORIGINAL"},
{"id":"p5-035","type":"context_vocabulary","sentence":"The company plans to _____ its operations into Southeast Asia next year.","options":["explain","expose","expire","expand"],"correctIndex":3,"explanation":{"coreStrategy":"空格後有 into Southeast Asia，表示把業務「擴展」到新市場，expand A into B 是固定用法。expire（到期）為不及物動詞；explain（解釋）、expose（暴露）語意不通。","structure":"S: The company / V: plans / O: to expand its operations / 修飾語: into Southeast Asia；next year"},"source":"ORIGINAL"},
{"id":"p5-036","type":"connector","sentence":"Mr. Davis prefers to work in the office, _____ his colleague enjoys working from home.","options":["whereas","despite","because of","therefore"],"correctIndex":0,"explanation":{"coreStrategy":"前後兩個子句是對比（他喜歡進辦公室，同事喜歡在家工作），需要表對比的連接詞 whereas。because of、despite 是介系詞，不能接子句；therefore 是副詞，且表因果，語意不通。","structure":"S: Mr. Davis / V: prefers / O: to work in the office / 修飾語: whereas his colleague enjoys working from home（對比子句）"},"source":"ORIGINAL"},
{"id":"p5-037","type":"preposition_collocation","sentence":"Mr. Lopez specializes _____ international tax law.","options":["in","at","for","to"],"correctIndex":0,"explanation":{"coreStrategy":"specialize in 表示「專精於」；與名詞 specialist in 的搭配相同。","structure":"S: Mr. Lopez / V: specializes in / O: international tax law / 修飾語: 無"},"source":"ORIGINAL"},
{"id":"p5-038","type":"part_of_speech","sentence":"Customer _____ is our highest priority.","options":["satisfaction","satisfy","satisfactory","satisfied"],"correctIndex":0,"explanation":{"coreStrategy":"空格與 Customer 組成主詞，後接動詞 is，需要名詞；customer satisfaction 是常見的複合名詞。","structure":"S: Customer satisfaction / V: is / O: 無（補語 our highest priority）/ 修飾語: 無"},"source":"ORIGINAL"},
{"id":"p5-039","type":"context_vocabulary","sentence":"Employees who wish to work from home must obtain _____ from their supervisor.","options":["submission","emission","permission","admission"],"correctIndex":2,"explanation":{"coreStrategy":"想在家工作的員工要向主管取得「許可」，obtain permission from 是常見說法。admission（入場、入學許可）、submission（提交）、emission（排放）都不符合向主管請求的情境。","structure":"S: Employees (who wish to work from home) / V: must obtain / O: permission / 修飾語: who wish to work from home（關係子句）；from their supervisor"},"source":"ORIGINAL"},
{"id":"p5-040","type":"connector","sentence":"The museum will remain open _____ the ongoing renovation work.","options":["despite","although","therefore","because"],"correctIndex":0,"explanation":{"coreStrategy":"空格後是名詞片語 the ongoing renovation work，需要介系詞；施工中卻照常開放，是讓步關係，選 despite。although、because 是連接詞，要接子句；therefore 是副詞，不能接名詞。","structure":"S: The museum / V: will remain / O: 無（補語 open）/ 修飾語: despite the ongoing renovation work"},"source":"ORIGINAL"},
{"id":"p5-041","type":"preposition_collocation","sentence":"The shipment was delayed due to a shortage _____ qualified truck drivers.","options":["at","with","by","of"],"correctIndex":3,"explanation":{"coreStrategy":"a shortage of + 名詞表示「……短缺」；空格前的名詞 shortage 是線索。","structure":"S: The shipment / V: was delayed / O: 無（被動語態）/ 修飾語: due to a shortage of qualified truck drivers"},"source":"ORIGINAL"},
{"id":"p5-042","type":"part_of_speech","sentence":"The keynote speaker gave an _____ presentation on artificial intelligence in logistics.","options":["informative","inform","information","informatively"],"correctIndex":0,"explanation":{"coreStrategy":"冠詞 an 與名詞 presentation 之間需要形容詞；-ive 結尾的 informative 表示「資訊豐富的」。","structure":"S: The keynote speaker / V: gave / O: an informative presentation / 修飾語: on artificial intelligence in logistics"},"source":"ORIGINAL"},
{"id":"p5-043","type":"context_vocabulary","sentence":"The conference room can _____ up to 80 people.","options":["accompany","accommodate","accomplish","accumulate"],"correctIndex":1,"explanation":{"coreStrategy":"主詞是會議室，後接 up to 80 people（最多 80 人），表示「容納」，用 accommodate。accumulate（累積）、accomplish（完成）、accompany（陪同）的主詞不會是房間。","structure":"S: The conference room / V: can accommodate / O: up to 80 people / 修飾語: 無"},"source":"ORIGINAL"},
{"id":"p5-044","type":"connector","sentence":"_____ she had little experience in sales, Ms. Grant quickly became the top performer in her department.","options":["Because","Despite","As a result","Even though"],"correctIndex":3,"explanation":{"coreStrategy":"空格後是子句 she had little experience，需要連接詞；經驗少卻成為業績第一，是讓步關係，選 Even though。Because 語意相反；Despite 是介系詞，不能接子句；As a result 是副詞片語，不能引導從屬子句。","structure":"S: Ms. Grant / V: became / O: 無（補語 the top performer）/ 修飾語: Even though she had little experience in sales（讓步子句）；quickly；in her department"},"source":"ORIGINAL"},
{"id":"p5-045","type":"preposition_collocation","sentence":"The conference room is equipped _____ a projector and a video-conferencing system.","options":["by","with","of","for"],"correctIndex":1,"explanation":{"coreStrategy":"be equipped with 表示「配備有」；by 表示動作執行者，此處設備不是執行者，不可選。","structure":"S: The conference room / V: is equipped with / O: a projector and a video-conferencing system / 修飾語: 無"},"source":"ORIGINAL"},
{"id":"p5-046","type":"part_of_speech","sentence":"The two companies have agreed to work _____ on the new research project.","options":["collaborative","collaboration","collaborate","collaboratively"],"correctIndex":3,"explanation":{"coreStrategy":"空格修飾不及物動詞 work，需要副詞；collaboratively 表示「合作地」。","structure":"S: The two companies / V: have agreed / O: to work collaboratively / 修飾語: on the new research project"},"source":"ORIGINAL"},
{"id":"p5-047","type":"context_vocabulary","sentence":"Because the printer is out of order, a technician has been called to _____ it.","options":["reply","repair","require","retain"],"correctIndex":1,"explanation":{"coreStrategy":"前半句說印表機故障（out of order），所以找技術人員來「修理」它，用 repair。reply（回覆）是不及物動詞；require（需要）、retain（保留）放入後語意不通。","structure":"S: a technician / V: has been called / O: 無（被動語態）/ 修飾語: Because the printer is out of order（副詞子句）；to repair it（表目的）"},"source":"ORIGINAL"},
{"id":"p5-048","type":"connector","sentence":"The road was closed _____ heavy snow.","options":["so that","because","although","due to"],"correctIndex":3,"explanation":{"coreStrategy":"空格後只有名詞片語 heavy snow，需要介系詞；大雪是封路的原因，選 due to。because、although、so that 都是連接詞，後面必須接子句。","structure":"S: The road / V: was closed / O: 無（被動語態）/ 修飾語: due to heavy snow"},"source":"ORIGINAL"},
{"id":"p5-049","type":"preposition_collocation","sentence":"Customers who are not satisfied _____ their purchase may return it within 30 days.","options":["of","at","to","with"],"correctIndex":3,"explanation":{"coreStrategy":"be satisfied with 表示「對……滿意」；與 be pleased with、be happy with 同一類搭配。","structure":"S: Customers (who are not satisfied with their purchase) / V: may return / O: it / 修飾語: who are not satisfied with their purchase（關係子句）；within 30 days"},"source":"ORIGINAL"},
{"id":"p5-050","type":"part_of_speech","sentence":"The board has _____ approved the merger plan.","options":["unanimous","unanimity","unanimously","unanimousness"],"correctIndex":2,"explanation":{"coreStrategy":"空格位於助動詞 has 與過去分詞 approved 之間，這個位置只能放副詞；unanimously 表示「全體一致地」。","structure":"S: The board / V: has approved / O: the merger plan / 修飾語: unanimously"},"source":"ORIGINAL"},
{"id":"p5-051","type":"context_vocabulary","sentence":"The survey results will be _____ at the next staff meeting.","options":["prevented","preserved","presented","pretended"],"correctIndex":2,"explanation":{"coreStrategy":"調查結果會在下次員工會議上「報告、發表」，present 有「提出、報告」之意。prevented（防止）、pretended（假裝）、preserved（保存）與會議情境不合。","structure":"S: The survey results / V: will be presented / O: 無（被動語態）/ 修飾語: at the next staff meeting"},"source":"ORIGINAL"},
{"id":"p5-052","type":"connector","sentence":"The restaurant was fully booked; _____, we decided to eat at the café next door.","options":["despite","although","consequently","nevertheless"],"correctIndex":2,"explanation":{"coreStrategy":"分號後加逗號的位置需要連接副詞；餐廳客滿是因，改去隔壁咖啡廳是果，選 consequently（因此）。nevertheless 表讓步，語意不通；although 是連接詞、despite 是介系詞，不能放在此處。","structure":"S: we / V: decided / O: to eat at the café next door / 修飾語: consequently；（前一子句 The restaurant was fully booked）"},"source":"ORIGINAL"},
{"id":"p5-053","type":"preposition_collocation","sentence":"The hotel is conveniently located close _____ the convention center.","options":["to","at","with","on"],"correctIndex":0,"explanation":{"coreStrategy":"close to 表示「靠近」；形容詞 close 表距離時固定接 to，同 next to、near to。","structure":"S: The hotel / V: is located / O: 無（被動語態）/ 修飾語: conveniently；close to the convention center"},"source":"ORIGINAL"},
{"id":"p5-054","type":"part_of_speech","sentence":"The _____ for the marketing position must have at least three years of experience.","options":["apply","applicant","application","applicable"],"correctIndex":1,"explanation":{"coreStrategy":"定冠詞 The 後要接名詞，且主詞必須是「人」才能 have experience；applicant（應徵者）是人，application（申請書）不是。","structure":"S: The applicant / V: must have / O: at least three years of experience / 修飾語: for the marketing position"},"source":"ORIGINAL"},
{"id":"p5-055","type":"context_vocabulary","sentence":"Mr. Kim's flight was delayed, so he was unable to _____ the opening ceremony.","options":["attend","attract","attempt","attach"],"correctIndex":0,"explanation":{"coreStrategy":"班機延誤導致無法「出席」開幕典禮，attend 後直接接活動名稱。attract（吸引）、attach（附加）、attempt（嘗試）放入後語意不通。","structure":"S: Mr. Kim's flight / V: was delayed / O: 無（被動語態）/ 修飾語: so he was unable to attend the opening ceremony（對等子句）"},"source":"ORIGINAL"},
{"id":"p5-056","type":"connector","sentence":"_____ having a limited budget, the team produced an impressive promotional video.","options":["Despite","Therefore","However","Because"],"correctIndex":0,"explanation":{"coreStrategy":"空格後是動名詞片語 having a limited budget，需要介系詞；預算有限卻做出出色影片，是讓步關係，選 Despite。Because 是連接詞，不能直接接動名詞；However、Therefore 是副詞，不能接動名詞片語。","structure":"S: the team / V: produced / O: an impressive promotional video / 修飾語: Despite having a limited budget"},"source":"ORIGINAL"},
{"id":"p5-057","type":"preposition_collocation","sentence":"In accordance _____ company policy, all receipts must be submitted within a week.","options":["with","to","of","by"],"correctIndex":0,"explanation":{"coreStrategy":"in accordance with 表示「依照、根據」，是規章與公告的固定片語。","structure":"S: all receipts / V: must be submitted / O: 無（被動語態）/ 修飾語: In accordance with company policy；within a week"},"source":"ORIGINAL"},
{"id":"p5-058","type":"part_of_speech","sentence":"Ms. Lee's _____ to detail made her the ideal choice for quality control.","options":["attend","attentive","attentively","attention"],"correctIndex":3,"explanation":{"coreStrategy":"所有格 Ms. Lee's 後要接名詞，attention to detail 表示「注重細節」。","structure":"S: Ms. Lee's attention to detail / V: made / O: her / 修飾語: the ideal choice（受詞補語）；for quality control"},"source":"ORIGINAL"},
{"id":"p5-059","type":"context_vocabulary","sentence":"To reduce costs, the firm decided to _____ its payroll processing to an outside agency.","options":["outgrow","outsource","outnumber","outlast"],"correctIndex":1,"explanation":{"coreStrategy":"空格後有 to an outside agency（交給外部機構），且目的是降低成本，表示「外包」，outsource A to B 是固定用法。outlast（比……持久）、outnumber（數量勝過）、outgrow（長大到不再適合）都不能接 to + 機構。","structure":"S: the firm / V: decided / O: to outsource its payroll processing / 修飾語: To reduce costs（表目的）；to an outside agency"},"source":"ORIGINAL"},
{"id":"p5-060","type":"connector","sentence":"Profits increased this year _____ the company's successful expansion into overseas markets.","options":["although","owing to","so","in spite of"],"correctIndex":1,"explanation":{"coreStrategy":"空格後是名詞片語，需要介系詞；成功拓展海外市場是獲利成長的原因，選 owing to（由於）。in spite of 雖是介系詞，但表讓步，語意相反；although、so 是連接詞，後面要接子句。","structure":"S: Profits / V: increased / O: 無（不及物動詞）/ 修飾語: this year；owing to the company's successful expansion into overseas markets"},"source":"ORIGINAL"},
{"id":"p5-061","type":"preposition_collocation","sentence":"The new factory will reduce our dependence _____ overseas suppliers.","options":["of","on","with","at"],"correctIndex":1,"explanation":{"coreStrategy":"名詞 dependence 沿用動詞 depend on 的搭配，dependence on 表示「對……的依賴」。","structure":"S: The new factory / V: will reduce / O: our dependence on overseas suppliers / 修飾語: on overseas suppliers（修飾 dependence）"},"source":"ORIGINAL"},
{"id":"p5-062","type":"part_of_speech","sentence":"The new printers are much more _____ than the old ones.","options":["reliably","reliability","rely","reliable"],"correctIndex":3,"explanation":{"coreStrategy":"be 動詞 are 後接比較級 more _____ than 當補語，需要形容詞 reliable；much 修飾比較級。","structure":"S: The new printers / V: are / O: 無（補語 much more reliable）/ 修飾語: than the old ones"},"source":"ORIGINAL"},
{"id":"p5-063","type":"context_vocabulary","sentence":"The museum's new exhibit has _____ more than 10,000 visitors in its first month.","options":["retracted","attracted","subtracted","contracted"],"correctIndex":1,"explanation":{"coreStrategy":"新展覽第一個月「吸引」超過一萬名訪客，attract visitors 是常見搭配。contracted（簽約、收縮）、retracted（撤回）、subtracted（減去）都是 -tract 字根誘答，語意不通。","structure":"S: The museum's new exhibit / V: has attracted / O: more than 10,000 visitors / 修飾語: in its first month"},"source":"ORIGINAL"},
{"id":"p5-064","type":"connector","sentence":"The CEO's speech was short; _____, it was very inspiring.","options":["because of","however","therefore","although"],"correctIndex":1,"explanation":{"coreStrategy":"分號後加逗號的位置需要連接副詞；「演講很短」與「很激勵人心」是轉折關係，選 however。therefore 表因果，語意不通；because of 是介系詞、although 是連接詞，不能放在分號後加逗號的位置。","structure":"S: it / V: was / O: 無（補語 very inspiring）/ 修飾語: however；（前一子句 The CEO's speech was short）"},"source":"ORIGINAL"},
{"id":"p5-065","type":"preposition_collocation","sentence":"Sales representatives are eligible _____ a bonus if they exceed their monthly targets.","options":["to","of","with","for"],"correctIndex":3,"explanation":{"coreStrategy":"be eligible for + 名詞表示「有資格獲得」；eligible to 後面要接原形動詞，空格後是名詞 a bonus，所以選 for。","structure":"S: Sales representatives / V: are eligible for / O: a bonus / 修飾語: if they exceed their monthly targets（條件子句）"},"source":"ORIGINAL"},
{"id":"p5-066","type":"part_of_speech","sentence":"Investors reacted _____ to the news of the merger.","options":["positive","positively","positivity","positiveness"],"correctIndex":1,"explanation":{"coreStrategy":"空格修飾不及物動詞 reacted，需要副詞 positively（正面地）。","structure":"S: Investors / V: reacted / O: 無（不及物動詞）/ 修飾語: positively；to the news of the merger"},"source":"ORIGINAL"},
{"id":"p5-067","type":"context_vocabulary","sentence":"Please read the contract carefully before you _____ it.","options":["design","align","sign","resign"],"correctIndex":2,"explanation":{"coreStrategy":"仔細閱讀合約後再「簽署」，sign a contract 是固定搭配。align（對齊）、design（設計）、resign（辭職）都無法以合約為受詞。","structure":"S: （you，祈使句省略）/ V: Please read / O: the contract / 修飾語: carefully；before you sign it（副詞子句）"},"source":"ORIGINAL"},
{"id":"p5-068","type":"connector","sentence":"_____ the instructions were clear, several employees made mistakes on the form.","options":["Due to","Despite","Though","Because"],"correctIndex":2,"explanation":{"coreStrategy":"空格後是子句，需要連接詞；說明清楚卻仍有人填錯，是讓步關係，選 Though。Because 語意相反；Despite、Due to 是介系詞，不能接子句。","structure":"S: several employees / V: made / O: mistakes / 修飾語: Though the instructions were clear（讓步子句）；on the form"},"source":"ORIGINAL"},
{"id":"p5-069","type":"preposition_collocation","sentence":"The training manual is available _____ request from the human resources department.","options":["upon","at","in","with"],"correctIndex":0,"explanation":{"coreStrategy":"available upon request 表示「可應要求提供」，是固定說法（也可寫 on request）。","structure":"S: The training manual / V: is available / O: 無（補語 available）/ 修飾語: upon request；from the human resources department"},"source":"ORIGINAL"},
{"id":"p5-070","type":"part_of_speech","sentence":"The survey results will help us _____ our customer service procedures.","options":["improvement","improve","improved","improving"],"correctIndex":1,"explanation":{"coreStrategy":"help + 受詞 + 原形動詞（或 to V）；us 後面接原形動詞 improve，且需要能帶受詞 procedures 的動詞。","structure":"S: The survey results / V: will help / O: us / 修飾語: improve our customer service procedures（受詞補語）"},"source":"ORIGINAL"},
{"id":"p5-071","type":"context_vocabulary","sentence":"Sales of the new smartphone have _____ expectations, so the company is increasing production.","options":["excused","exceeded","excluded","exchanged"],"correctIndex":1,"explanation":{"coreStrategy":"後半句說公司要增產，可知銷量「超出」預期，exceed expectations 是常見搭配。excluded（排除）、excused（原諒）、exchanged（交換）語意不通。","structure":"S: Sales of the new smartphone / V: have exceeded / O: expectations / 修飾語: so the company is increasing production（對等子句）"},"source":"ORIGINAL"},
{"id":"p5-072","type":"connector","sentence":"The factory upgraded its equipment, and _____ production costs fell by 15 percent.","options":["despite","although","as a result","because of"],"correctIndex":2,"explanation":{"coreStrategy":"and 後面是完整子句 production costs fell，空格需要可插入句中的連接副詞片語；升級設備是因，成本下降是果，選 as a result。despite、because of 是介系詞，不能接子句；although 放入後會使 and 之後只剩從屬子句，句子不完整。","structure":"S: The factory / V: upgraded / O: its equipment / 修飾語: and as a result production costs fell by 15 percent（對等子句）"},"source":"ORIGINAL"},
{"id":"p5-073","type":"preposition_collocation","sentence":"Due to the storm, the flight was canceled, and passengers were provided _____ hotel vouchers.","options":["for","to","with","of"],"correctIndex":2,"explanation":{"coreStrategy":"provide A with B 表示「提供 B 給 A」；被動 A be provided with B，人當主詞時接 with。","structure":"S: passengers / V: were provided with / O: hotel vouchers / 修飾語: Due to the storm；（前一子句 the flight was canceled）"},"source":"ORIGINAL"},
{"id":"p5-074","type":"part_of_speech","sentence":"The financial report must be reviewed by an _____ auditor.","options":["independently","independent","independence","depend"],"correctIndex":1,"explanation":{"coreStrategy":"冠詞 an 與名詞 auditor 之間要放形容詞；independent auditor 表示「獨立的稽核人員」。","structure":"S: The financial report / V: must be reviewed / O: 無（被動語態）/ 修飾語: by an independent auditor"},"source":"ORIGINAL"},
{"id":"p5-075","type":"context_vocabulary","sentence":"The maintenance team will _____ the elevators every month to ensure they are safe.","options":["insist","inspire","inspect","insert"],"correctIndex":2,"explanation":{"coreStrategy":"to ensure they are safe（確保安全）是線索，維修團隊每月「檢查」電梯，用 inspect。insist（堅持）不直接接受詞；inspire（激勵）、insert（插入）語意不通。","structure":"S: The maintenance team / V: will inspect / O: the elevators / 修飾語: every month；to ensure they are safe（表目的）"},"source":"ORIGINAL"},
{"id":"p5-076","type":"connector","sentence":"_____ the high demand for tickets, the organizers added a second performance.","options":["Because","Although","Despite","Because of"],"correctIndex":3,"explanation":{"coreStrategy":"空格後是名詞片語 the high demand for tickets，需要介系詞；票券需求高是加演的原因，選 Because of。Despite 表讓步，語意相反；Although、Because 是連接詞，不能接名詞片語。","structure":"S: the organizers / V: added / O: a second performance / 修飾語: Because of the high demand for tickets"},"source":"ORIGINAL"},
{"id":"p5-077","type":"preposition_collocation","sentence":"The CEO expressed her gratitude to the team _____ their hard work during the merger.","options":["of","for","on","at"],"correctIndex":1,"explanation":{"coreStrategy":"express gratitude to 人 for 事，表示「為某事向某人致謝」；感謝的原因用 for。","structure":"S: The CEO / V: expressed / O: her gratitude / 修飾語: to the team；for their hard work；during the merger"},"source":"ORIGINAL"},
{"id":"p5-078","type":"part_of_speech","sentence":"Please handle the glass containers _____ because they break easily.","options":["gentle","gentleness","gentlest","gently"],"correctIndex":3,"explanation":{"coreStrategy":"handle the glass containers 已是完整的動詞＋受詞，空格修飾動作 handle，需要副詞 gently。","structure":"S: （you，祈使句省略）/ V: Please handle / O: the glass containers / 修飾語: gently；because they break easily"},"source":"ORIGINAL"},
{"id":"p5-079","type":"context_vocabulary","sentence":"Due to a high volume of orders, deliveries may take longer than _____.","options":["usual","casual","mutual","actual"],"correctIndex":0,"explanation":{"coreStrategy":"longer than usual 是固定說法，意為「比平常久」；前面說訂單量大，所以配送時間比平常長。actual（實際的）、casual（隨意的）、mutual（互相的）都不能接在 than 後面表示比較基準。","structure":"S: deliveries / V: may take / O: 無（不及物用法，longer 為副詞）/ 修飾語: Due to a high volume of orders；longer than usual"},"source":"ORIGINAL"},
{"id":"p5-080","type":"connector","sentence":"The project was completed on time _____ the team faced several unexpected problems.","options":["in spite of","even though","so that","because"],"correctIndex":1,"explanation":{"coreStrategy":"空格後是子句 the team faced several unexpected problems，需要連接詞；遇到問題仍準時完成，是讓步關係，選 even though。because 表原因、so that 表目的，語意都不通；in spite of 是介系詞，不能接子句。","structure":"S: The project / V: was completed / O: 無（被動語態）/ 修飾語: on time；even though the team faced several unexpected problems（讓步子句）"},"source":"ORIGINAL"},
{"id":"p5-081","type":"preposition_collocation","sentence":"Mr. Kim is familiar _____ the procedures for processing international orders.","options":["to","at","by","with"],"correctIndex":3,"explanation":{"coreStrategy":"人 + be familiar with + 事物，表示「熟悉」；be familiar to 的主詞必須是事物（The procedures are familiar to Mr. Kim）。","structure":"S: Mr. Kim / V: is familiar with / O: the procedures / 修飾語: for processing international orders"},"source":"ORIGINAL"},
{"id":"p5-082","type":"part_of_speech","sentence":"Mr. Ortiz has been a _____ contributor to the company newsletter for years.","options":["regular","regularly","regularity","regulate"],"correctIndex":0,"explanation":{"coreStrategy":"冠詞 a 與名詞 contributor 之間要放形容詞；regular contributor 表示「固定撰稿人」。","structure":"S: Mr. Ortiz / V: has been / O: 無（補語 a regular contributor）/ 修飾語: to the company newsletter；for years"},"source":"ORIGINAL"},
{"id":"p5-083","type":"context_vocabulary","sentence":"Customers can track the _____ of their orders on our website.","options":["stature","statue","statute","status"],"correctIndex":3,"explanation":{"coreStrategy":"在網站上追蹤訂單的「狀態」，track the status of 是電商常見用語。statue（雕像）、stature（身高、聲望）、statute（法令）拼字相近，語意不通。","structure":"S: Customers / V: can track / O: the status / 修飾語: of their orders；on our website"},"source":"ORIGINAL"},
{"id":"p5-084","type":"connector","sentence":"Some customers prefer to shop online, _____ others still like visiting physical stores.","options":["while","because of","therefore","despite"],"correctIndex":0,"explanation":{"coreStrategy":"前後兩個子句形成對比（有人愛網購，有人愛實體店），需要表對比的連接詞 while。because of、despite 是介系詞，不能接子句；therefore 是副詞，且表因果，語意不通。","structure":"S: Some customers / V: prefer / O: to shop online / 修飾語: while others still like visiting physical stores（對比子句）"},"source":"ORIGINAL"},
{"id":"p5-085","type":"preposition_collocation","sentence":"The museum will be closed to the public _____ the duration of the renovation.","options":["in","for","at","by"],"correctIndex":1,"explanation":{"coreStrategy":"for the duration of 表示「在……整段期間」，是固定片語。","structure":"S: The museum / V: will be closed / O: 無（被動語態）/ 修飾語: to the public；for the duration of the renovation"},"source":"ORIGINAL"},
{"id":"p5-086","type":"part_of_speech","sentence":"The museum's new exhibit is expected to attract a large number of _____.","options":["visit","visitors","visited","visiting"],"correctIndex":1,"explanation":{"coreStrategy":"a large number of 後接可數名詞複數；visitors（參觀者）是複數名詞，符合「吸引人潮」的語意。","structure":"S: The museum's new exhibit / V: is expected / O: to attract a large number of visitors / 修飾語: 無"},"source":"ORIGINAL"},
{"id":"p5-087","type":"context_vocabulary","sentence":"Our accountant is extremely _____, so she rarely makes errors in her reports.","options":["generous","meticulous","talkative","forgetful"],"correctIndex":1,"explanation":{"coreStrategy":"so 後面是結果：她很少出錯，前面應是「一絲不苟、極為細心的」特質，用 meticulous。generous（慷慨的）、talkative（健談的）與少出錯沒有因果關係；forgetful（健忘的）則與結果相反。","structure":"S: Our accountant / V: is / O: 無（補語 meticulous）/ 修飾語: extremely；so she rarely makes errors in her reports（對等子句）"},"source":"ORIGINAL"},
{"id":"p5-088","type":"connector","sentence":"The office will be closed on Monday _____ the national holiday.","options":["on account of","even though","as a result","in spite of"],"correctIndex":0,"explanation":{"coreStrategy":"空格後是名詞片語 the national holiday，需要介系詞；國定假日是休息的原因，選 on account of（因為）。in spite of 表讓步，語意相反；even though 是連接詞，要接子句；as a result 是副詞片語，後面不能直接接名詞（要用 as a result of）。","structure":"S: The office / V: will be closed / O: 無（被動語態）/ 修飾語: on Monday；on account of the national holiday"},"source":"ORIGINAL"},
{"id":"p5-089","type":"preposition_collocation","sentence":"Our client has expressed concern _____ the rising cost of raw materials.","options":["at","to","about","in"],"correctIndex":2,"explanation":{"coreStrategy":"express concern about 表示「對……表示擔憂」；concern 表「擔心」時接 about（或 over）。","structure":"S: Our client / V: has expressed / O: concern / 修飾語: about the rising cost of raw materials"},"source":"ORIGINAL"},
{"id":"p5-090","type":"part_of_speech","sentence":"The team leader spoke _____ about the challenges facing the department.","options":["frank","frankly","frankness","franker"],"correctIndex":1,"explanation":{"coreStrategy":"空格修飾不及物動詞 spoke，需要副詞；frankly 表示「坦白地」。","structure":"S: The team leader / V: spoke / O: 無（不及物動詞）/ 修飾語: frankly；about the challenges facing the department"},"source":"ORIGINAL"},
{"id":"p5-091","type":"context_vocabulary","sentence":"The _____ for submitting proposals is 5 P.M. on Friday.","options":["borderline","deadline","headline","guideline"],"correctIndex":1,"explanation":{"coreStrategy":"主詞補語是時間 5 P.M. on Friday，因此主詞是提交提案的「截止期限」，用 deadline。headline（標題）、guideline（準則）、borderline（界線）都不會等於一個時間點。","structure":"S: The deadline (for submitting proposals) / V: is / O: 無（補語 5 P.M. on Friday）/ 修飾語: for submitting proposals"},"source":"ORIGINAL"},
{"id":"p5-092","type":"connector","sentence":"Our old supplier often delivered late; _____, we switched to a more reliable company.","options":["despite","however","although","thus"],"correctIndex":3,"explanation":{"coreStrategy":"分號後加逗號的位置需要連接副詞；供應商常遲交是因，換廠商是果，選 thus（因此）。however 表轉折，語意不通；although 是連接詞、despite 是介系詞，不能放在此處。","structure":"S: we / V: switched / O: 無（不及物動詞）/ 修飾語: thus；to a more reliable company；（前一子句 Our old supplier often delivered late）"},"source":"ORIGINAL"},
{"id":"p5-093","type":"preposition_collocation","sentence":"The new policy applies _____ all full-time and part-time employees.","options":["of","to","at","with"],"correctIndex":1,"explanation":{"coreStrategy":"apply to 表示「適用於」；apply to 不可換成其他介系詞（apply for 是「申請」）。","structure":"S: The new policy / V: applies to / O: all full-time and part-time employees / 修飾語: 無"},"source":"ORIGINAL"},
{"id":"p5-094","type":"part_of_speech","sentence":"Reservations are strongly recommended because space is _____.","options":["limit","limitation","limits","limited"],"correctIndex":3,"explanation":{"coreStrategy":"be 動詞 is 後接形容詞當補語描述主詞 space；limited 表示「有限的」。limit、limits、limitation 都是名詞或動詞，放在這裡不合語法。","structure":"S: Reservations / V: are recommended / O: 無（被動語態）/ 修飾語: strongly；because space is limited"},"source":"ORIGINAL"},
{"id":"p5-095","type":"context_vocabulary","sentence":"The restaurant is so popular that _____ are recommended, especially on weekends.","options":["preservations","reservations","conversations","observations"],"correctIndex":1,"explanation":{"coreStrategy":"so popular that 表示結果：餐廳很熱門，所以建議「訂位」，reservation 意為「預約」。conversations（對話）、observations（觀察）、preservations（保存）都與熱門餐廳的建議無關。","structure":"S: The restaurant / V: is / O: 無（補語 so popular）/ 修飾語: that reservations are recommended, especially on weekends（結果子句）"},"source":"ORIGINAL"},
{"id":"p5-096","type":"connector","sentence":"_____ the train was delayed, Mr. Ito missed the opening session of the conference.","options":["Despite","Although","Because","Due to"],"correctIndex":2,"explanation":{"coreStrategy":"空格後是子句，需要連接詞；火車誤點是錯過開場的原因，選 Because。Although 表讓步，語意相反；Despite、Due to 是介系詞，不能接子句。","structure":"S: Mr. Ito / V: missed / O: the opening session / 修飾語: Because the train was delayed（原因子句）；of the conference"},"source":"ORIGINAL"},
{"id":"p5-097","type":"preposition_collocation","sentence":"The company has invested heavily _____ renewable energy projects.","options":["on","at","to","in"],"correctIndex":3,"explanation":{"coreStrategy":"invest in 表示「投資於」；中間的副詞 heavily 不影響搭配。","structure":"S: The company / V: has invested in / O: renewable energy projects / 修飾語: heavily"},"source":"ORIGINAL"},
{"id":"p5-098","type":"part_of_speech","sentence":"The software update will be installed _____ on all company computers tonight.","options":["automatic","automate","automatically","automation"],"correctIndex":2,"explanation":{"coreStrategy":"被動語態 will be installed 已完整，空格修飾動詞，需要副詞 automatically。","structure":"S: The software update / V: will be installed / O: 無（被動語態）/ 修飾語: automatically；on all company computers；tonight"},"source":"ORIGINAL"},
{"id":"p5-099","type":"context_vocabulary","sentence":"Ms. Patel will _____ the training workshop while the director is away.","options":["confess","conflict","conduct","conceal"],"correctIndex":2,"explanation":{"coreStrategy":"主任不在時由 Ms. Patel「主持、帶領」訓練課程，conduct a workshop 是常見搭配。conflict（衝突）是不及物動詞；confess（坦承）、conceal（隱藏）語意不通。","structure":"S: Ms. Patel / V: will conduct / O: the training workshop / 修飾語: while the director is away（副詞子句）"},"source":"ORIGINAL"},
{"id":"p5-100","type":"connector","sentence":"The hotel is located far from the city center; _____, many guests choose to stay there for its beautiful view.","options":["as a result","because","nonetheless","therefore"],"correctIndex":2,"explanation":{"coreStrategy":"分號後加逗號的位置需要連接副詞；「離市中心遠」與「很多人選擇入住」是讓步關係，選 nonetheless（儘管如此）。therefore、as a result 表因果，語意不通；because 是連接詞，不能放在分號後加逗號的位置。","structure":"S: many guests / V: choose / O: to stay there / 修飾語: nonetheless；for its beautiful view；（前一子句 The hotel is located far from the city center）"},"source":"ORIGINAL"},
{"id":"p5-101","type":"preposition_collocation","sentence":"Ms. Patel was promoted to regional manager _____ recognition of her outstanding performance.","options":["on","for","at","in"],"correctIndex":3,"explanation":{"coreStrategy":"in recognition of 表示「為了表彰」，是固定片語。","structure":"S: Ms. Patel / V: was promoted / O: 無（被動語態）/ 修飾語: to regional manager；in recognition of her outstanding performance"},"source":"ORIGINAL"},
{"id":"p5-102","type":"part_of_speech","sentence":"Despite the _____ of the task, the team finished it on schedule.","options":["complicated","complexity","complexly","complicate"],"correctIndex":1,"explanation":{"coreStrategy":"the _____ of 結構中空格要放名詞；-ity 結尾的 complexity 表示「複雜性」。","structure":"S: the team / V: finished / O: it / 修飾語: Despite the complexity of the task；on schedule"},"source":"ORIGINAL"},
{"id":"p5-103","type":"context_vocabulary","sentence":"We apologize for any _____ caused by the temporary closure of the parking lot.","options":["inconvenience","innocence","independence","intelligence"],"correctIndex":0,"explanation":{"coreStrategy":"apologize for any inconvenience caused by 是公告中最常見的致歉句型，意為「造成不便，敬請見諒」。independence（獨立）、intelligence（智力）、innocence（清白）都不是停車場關閉造成的結果。","structure":"S: We / V: apologize for / O: any inconvenience / 修飾語: caused by the temporary closure of the parking lot（過去分詞片語修飾 inconvenience）"},"source":"ORIGINAL"},
{"id":"p5-104","type":"connector","sentence":"_____ the positive reviews, the film did poorly at the box office.","options":["Because of","Due to","Even though","In spite of"],"correctIndex":3,"explanation":{"coreStrategy":"空格後是名詞片語 the positive reviews，需要介系詞；好評卻票房差，是讓步關係，選 In spite of。Because of、Due to 表原因，語意相反；Even though 是連接詞，要接子句。","structure":"S: the film / V: did / O: 無（不及物用法）/ 修飾語: In spite of the positive reviews；poorly；at the box office"},"source":"ORIGINAL"},
{"id":"p5-105","type":"preposition_collocation","sentence":"The proposal was rejected _____ the grounds that it exceeded the budget.","options":["on","in","at","by"],"correctIndex":0,"explanation":{"coreStrategy":"on the grounds that + 子句表示「以……為理由」，是固定片語。","structure":"S: The proposal / V: was rejected / O: 無（被動語態）/ 修飾語: on the grounds that it exceeded the budget"},"source":"ORIGINAL"},
{"id":"p5-106","type":"part_of_speech","sentence":"The new policy will be _____ next Monday.","options":["effect","effective","effectively","effectiveness"],"correctIndex":1,"explanation":{"coreStrategy":"be 動詞後接形容詞當補語；be effective + 時間表示「（法規）自……起生效」。","structure":"S: The new policy / V: will be / O: 無（補語 effective）/ 修飾語: next Monday"},"source":"ORIGINAL"},
{"id":"p5-107","type":"context_vocabulary","sentence":"The quarterly report shows a sharp _____ in online sales compared to last year.","options":["intention","increase","instance","invoice"],"correctIndex":1,"explanation":{"coreStrategy":"a sharp ___ in sales compared to last year 描述數字變化，需要「增加」，an increase in 是固定說法。instance（例子）、invoice（發票）、intention（意圖）都不能描述銷售額的變化幅度。","structure":"S: The quarterly report / V: shows / O: a sharp increase / 修飾語: in online sales；compared to last year"},"source":"ORIGINAL"},
{"id":"p5-108","type":"connector","sentence":"Ms. Chen was promoted _____ her excellent leadership skills.","options":["despite","whereas","although","because of"],"correctIndex":3,"explanation":{"coreStrategy":"空格後是名詞片語 her excellent leadership skills，需要介系詞；優秀的領導能力是升遷的原因，選 because of。despite 表讓步，語意相反；although、whereas 是連接詞，要接子句。","structure":"S: Ms. Chen / V: was promoted / O: 無（被動語態）/ 修飾語: because of her excellent leadership skills"},"source":"ORIGINAL"},
{"id":"p5-109","type":"preposition_collocation","sentence":"Seats at the seminar will be assigned _____ a first-come, first-served basis.","options":["in","on","at","by"],"correctIndex":1,"explanation":{"coreStrategy":"on a … basis 表示「以……方式」，如 on a daily basis、on a first-come, first-served basis。","structure":"S: Seats / V: will be assigned / O: 無（被動語態）/ 修飾語: at the seminar（修飾 Seats）；on a first-come, first-served basis"},"source":"ORIGINAL"},
{"id":"p5-110","type":"part_of_speech","sentence":"Ms. Novak is _____ for organizing the annual company retreat.","options":["responsibly","responsible","responsibility","respond"],"correctIndex":1,"explanation":{"coreStrategy":"be 動詞後需要形容詞補語，且 be responsible for 是固定搭配，表示「負責」。","structure":"S: Ms. Novak / V: is responsible for / O: organizing the annual company retreat / 修飾語: 無"},"source":"ORIGINAL"},
{"id":"p5-111","type":"context_vocabulary","sentence":"Job applicants should have at least three years of relevant _____ in sales.","options":["expense","experiment","experience","expectation"],"correctIndex":2,"explanation":{"coreStrategy":"three years of relevant ___ 是徵才廣告的典型條件，指相關「經驗」，用 experience。experiment（實驗）、expense（費用）、expectation（期待）不能以年資計算。","structure":"S: Job applicants / V: should have / O: at least three years of relevant experience / 修飾語: in sales"},"source":"ORIGINAL"},
{"id":"p5-112","type":"connector","sentence":"The printer is not working properly, _____ please use the one on the second floor.","options":["although","despite","because","so"],"correctIndex":3,"explanation":{"coreStrategy":"逗號後是祈使句，表示前句造成的結果（印表機故障，所以請用二樓那台），選對等連接詞 so。because、although 後面不能接祈使句，語意也不通；despite 是介系詞，不能接子句。","structure":"S: The printer / V: is not working / O: 無（不及物動詞）/ 修飾語: properly；so please use the one on the second floor（對等子句，祈使句）"},"source":"ORIGINAL"},
{"id":"p5-113","type":"preposition_collocation","sentence":"Please make sure the documents are signed and returned _____ the end of the month.","options":["until","since","during","by"],"correctIndex":3,"explanation":{"coreStrategy":"return（繳回）是一次完成的動作，表「最晚在……之前」用 by；until 要搭配持續性動作，since 要用完成式，during 表期間內。","structure":"S: （you，祈使句省略）/ V: Please make sure / O: (that) the documents are signed and returned / 修飾語: by the end of the month"},"source":"ORIGINAL"},
{"id":"p5-114","type":"part_of_speech","sentence":"The number of online orders has increased _____ over the past three years.","options":["steady","steadiness","steadied","steadily"],"correctIndex":3,"explanation":{"coreStrategy":"空格修飾不及物動詞 increased，需要副詞；steadily 表示「穩定地」。","structure":"S: The number of online orders / V: has increased / O: 無（不及物動詞）/ 修飾語: steadily；over the past three years"},"source":"ORIGINAL"},
{"id":"p5-115","type":"context_vocabulary","sentence":"The CEO thanked the employees for their hard work and _____ to the company.","options":["dedication","education","indication","medication"],"correctIndex":0,"explanation":{"coreStrategy":"與 hard work 並列、後接 to the company，表示對公司的「奉獻、投入」，dedication to 是固定搭配。medication（藥物）、indication（跡象）、education（教育）語意不通。","structure":"S: The CEO / V: thanked / O: the employees / 修飾語: for their hard work and dedication to the company"},"source":"ORIGINAL"},
{"id":"p5-116","type":"connector","sentence":"_____ the company's revenue grew, its profits remained flat because of rising costs.","options":["Therefore","Because","Despite","Although"],"correctIndex":3,"explanation":{"coreStrategy":"空格後是子句，需要連接詞；營收成長但獲利持平，是讓步關係，選 Although。Because 表原因，語意不通；Despite 是介系詞，不能接子句；Therefore 是副詞，不能引導從屬子句。","structure":"S: its profits / V: remained / O: 無（補語 flat）/ 修飾語: Although the company's revenue grew（讓步子句）；because of rising costs"},"source":"ORIGINAL"},
{"id":"p5-117","type":"preposition_collocation","sentence":"The marketing director is accountable _____ the board for the campaign's results.","options":["to","with","at","by"],"correctIndex":0,"explanation":{"coreStrategy":"be accountable to 人 for 事，表示「就某事對某人負責」；句中已有 for 帶出事，空格後是人（the board），選 to。","structure":"S: The marketing director / V: is accountable / O: 無（補語 accountable）/ 修飾語: to the board；for the campaign's results"},"source":"ORIGINAL"},
{"id":"p5-118","type":"part_of_speech","sentence":"The marketing team prepared a _____ analysis of competitors' pricing.","options":["thoroughly","thoroughness","more thoroughly","thorough"],"correctIndex":3,"explanation":{"coreStrategy":"冠詞 a 與名詞 analysis 之間要放形容詞；thorough 表示「徹底的、周詳的」。","structure":"S: The marketing team / V: prepared / O: a thorough analysis / 修飾語: of competitors' pricing"},"source":"ORIGINAL"},
{"id":"p5-119","type":"context_vocabulary","sentence":"Passengers are reminded not to leave their bags _____ at any time.","options":["unemployed","unanimous","unlimited","unattended"],"correctIndex":3,"explanation":{"coreStrategy":"leave + 受詞 + 補語：不要讓行李處於「無人看管」的狀態，leave bags unattended 是機場、車站廣播的固定說法。unemployed（失業的）、unlimited（無限的）、unanimous（一致同意的）不能描述行李。","structure":"S: Passengers / V: are reminded / O: 無（被動語態）/ 修飾語: not to leave their bags unattended（unattended 為受詞補語）；at any time"},"source":"ORIGINAL"},
{"id":"p5-120","type":"connector","sentence":"_____ heavy traffic on the highway, the bus arrived 30 minutes late.","options":["Because","Although","Due to","Despite"],"correctIndex":2,"explanation":{"coreStrategy":"空格後是名詞片語 heavy traffic，需要介系詞；塞車是誤點的原因，選 Due to。Despite 雖是介系詞，但表讓步，語意相反；Although、Because 是連接詞，要接子句。","structure":"S: the bus / V: arrived / O: 無（不及物動詞）/ 修飾語: Due to heavy traffic on the highway；30 minutes late"},"source":"ORIGINAL"},
{"id":"p5-121","type":"preposition_collocation","sentence":"Employees are encouraged to take advantage _____ the free language courses offered on site.","options":["for","of","to","with"],"correctIndex":1,"explanation":{"coreStrategy":"take advantage of 表示「利用」，是固定片語。","structure":"S: Employees / V: are encouraged / O: to take advantage of the free language courses / 修飾語: offered on site（修飾 courses）"},"source":"ORIGINAL"},
{"id":"p5-122","type":"part_of_speech","sentence":"Ms. Ahmed was hired because of her _____ knowledge of supply chain management.","options":["extensively","extensive","extension","extend"],"correctIndex":1,"explanation":{"coreStrategy":"所有格 her 與名詞 knowledge 之間要放形容詞；extensive knowledge 表示「廣博的知識」。","structure":"S: Ms. Ahmed / V: was hired / O: 無（被動語態）/ 修飾語: because of her extensive knowledge of supply chain management"},"source":"ORIGINAL"},
{"id":"p5-123","type":"context_vocabulary","sentence":"The city council voted to _____ the old factory into a community arts center.","options":["convince","convert","convey","convict"],"correctIndex":1,"explanation":{"coreStrategy":"空格後有 into a community arts center，表示把舊工廠「改建、轉換」成藝文中心，convert A into B 是固定用法。convict（定罪）、convince（說服）、convey（傳達）都不接 A into B。","structure":"S: The city council / V: voted / O: to convert the old factory / 修飾語: into a community arts center"},"source":"ORIGINAL"},
{"id":"p5-124","type":"connector","sentence":"Many employees chose the morning shift, _____ only a few signed up for the evening shift.","options":["whereas","therefore","because","due to"],"correctIndex":0,"explanation":{"coreStrategy":"前後兩個子句形成對比（很多人選早班，只有少數選晚班），選表對比的連接詞 whereas。because 表原因，語意不通；due to 是介系詞，不能接子句；therefore 是副詞，不能用逗號連接兩個子句。","structure":"S: Many employees / V: chose / O: the morning shift / 修飾語: whereas only a few signed up for the evening shift（對比子句）"},"source":"ORIGINAL"},
{"id":"p5-125","type":"preposition_collocation","sentence":"The newly hired engineers will be assigned _____ the product development team.","options":["with","at","for","to"],"correctIndex":3,"explanation":{"coreStrategy":"assign A to B 表示「把 A 分派到 B」；被動 A be assigned to B。","structure":"S: The newly hired engineers / V: will be assigned to / O: the product development team / 修飾語: newly hired"},"source":"ORIGINAL"},
{"id":"p5-126","type":"part_of_speech","sentence":"Employees who wish to work remotely must obtain _____ from their department head.","options":["permissive","permissible","permission","permissively"],"correctIndex":2,"explanation":{"coreStrategy":"及物動詞 obtain 後面需要名詞當受詞；permission 是不可數名詞，前面不需冠詞。","structure":"S: Employees (who wish to work remotely) / V: must obtain / O: permission / 修飾語: who wish to work remotely（關係子句）；from their department head"},"source":"ORIGINAL"},
{"id":"p5-127","type":"context_vocabulary","sentence":"Because the instructions were _____, many users had trouble assembling the desk.","options":["unpaid","uninsured","unoccupied","unclear"],"correctIndex":3,"explanation":{"coreStrategy":"主要子句說使用者組裝有困難，原因應是說明書「不清楚」，用 unclear。unpaid（未付款的）、uninsured（未投保的）、unoccupied（無人使用的）都不能描述說明書，也無法造成組裝困難。","structure":"S: many users / V: had / O: trouble / 修飾語: Because the instructions were unclear（副詞子句）；assembling the desk"},"source":"ORIGINAL"},
{"id":"p5-128","type":"connector","sentence":"_____ the manager was on vacation, her assistant handled all urgent requests.","options":["Since","Despite","However","Due to"],"correctIndex":0,"explanation":{"coreStrategy":"空格後是子句，需要連接詞；經理休假是助理代為處理的原因，since 在此作「因為」解。Despite、Due to 是介系詞，不能接子句；However 是副詞，不能引導從屬子句。","structure":"S: her assistant / V: handled / O: all urgent requests / 修飾語: Since the manager was on vacation（原因子句）"},"source":"ORIGINAL"},
{"id":"p5-129","type":"preposition_collocation","sentence":"Ms. Rivera will be acting _____ behalf of the director while he is on leave.","options":["at","on","by","to"],"correctIndex":1,"explanation":{"coreStrategy":"on behalf of 表示「代表、代理」，是固定片語。","structure":"S: Ms. Rivera / V: will be acting / O: 無 / 修飾語: on behalf of the director；while he is on leave"},"source":"ORIGINAL"},
{"id":"p5-130","type":"part_of_speech","sentence":"The product launch was postponed _____ because of a manufacturing defect.","options":["temporarily","temporary","temporariness","temporal"],"correctIndex":0,"explanation":{"coreStrategy":"被動語態 was postponed 已完整，空格修飾動詞，需要副詞 temporarily（暫時地）。","structure":"S: The product launch / V: was postponed / O: 無（被動語態）/ 修飾語: temporarily；because of a manufacturing defect"},"source":"ORIGINAL"},
{"id":"p5-131","type":"context_vocabulary","sentence":"The marketing director asked her team to _____ ideas for the upcoming campaign.","options":["tolerate","terminate","evaporate","generate"],"correctIndex":3,"explanation":{"coreStrategy":"為即將到來的行銷活動「發想、產生」點子，generate ideas 是常見搭配。terminate（終止）、tolerate（容忍）、evaporate（蒸發）放入後語意不通。","structure":"S: The marketing director / V: asked / O: her team / 修飾語: to generate ideas for the upcoming campaign（受詞補語）"},"source":"ORIGINAL"},
{"id":"p5-132","type":"connector","sentence":"The tablet is lighter than previous models _____ it has a larger screen.","options":["because of","therefore","although","despite"],"correctIndex":2,"explanation":{"coreStrategy":"空格後是子句 it has a larger screen，需要連接詞；螢幕更大卻更輕，是讓步關係，選 although。because of、despite 是介系詞，不能接子句；therefore 是副詞，且表因果，語意不通。","structure":"S: The tablet / V: is / O: 無（補語 lighter than previous models）/ 修飾語: although it has a larger screen（讓步子句）"},"source":"ORIGINAL"},
{"id":"p5-133","type":"preposition_collocation","sentence":"We apologize _____ any inconvenience the system maintenance may cause.","options":["of","with","for","to"],"correctIndex":2,"explanation":{"coreStrategy":"apologize for 事、apologize to 人；空格後是事情（inconvenience），選 for。","structure":"S: We / V: apologize for / O: any inconvenience / 修飾語: (that) the system maintenance may cause（關係子句）"},"source":"ORIGINAL"},
{"id":"p5-134","type":"part_of_speech","sentence":"Our consultants provide _____ advice to small business owners.","options":["practically","practice","practicality","practical"],"correctIndex":3,"explanation":{"coreStrategy":"空格在名詞 advice 前，需要形容詞；practical advice 表示「實用的建議」。","structure":"S: Our consultants / V: provide / O: practical advice / 修飾語: to small business owners"},"source":"ORIGINAL"},
{"id":"p5-135","type":"context_vocabulary","sentence":"The store will _____ a full refund if the product is returned within 30 days.","options":["inquire","insist","issue","install"],"correctIndex":2,"explanation":{"coreStrategy":"商店「核發」全額退款，issue a refund 是固定搭配。insist（堅持）、inquire（詢問）不直接接 a refund 當受詞；install（安裝）語意不通。","structure":"S: The store / V: will issue / O: a full refund / 修飾語: if the product is returned within 30 days（條件子句）"},"source":"ORIGINAL"},
{"id":"p5-136","type":"connector","sentence":"Online orders increased dramatically during the holiday season; _____, the company hired temporary warehouse staff.","options":["accordingly","otherwise","however","nevertheless"],"correctIndex":0,"explanation":{"coreStrategy":"分號後加逗號的位置需要連接副詞；訂單暴增是因，加聘臨時倉儲人員是果，選 accordingly（因此、相應地）。however、nevertheless 表轉折；otherwise 意為「否則」，語意都不通。","structure":"S: the company / V: hired / O: temporary warehouse staff / 修飾語: accordingly；（前一子句 Online orders increased dramatically during the holiday season）"},"source":"ORIGINAL"},
{"id":"p5-137","type":"preposition_collocation","sentence":"The lease agreement is subject _____ approval by the legal department.","options":["for","of","to","with"],"correctIndex":2,"explanation":{"coreStrategy":"be subject to 表示「須經……；以……為條件」，合約與公告常用。","structure":"S: The lease agreement / V: is subject to / O: approval / 修飾語: by the legal department"},"source":"ORIGINAL"},
{"id":"p5-138","type":"part_of_speech","sentence":"The company is seeking a _____ to manage its social media accounts.","options":["specialist","specialize","specialized","specialty"],"correctIndex":0,"explanation":{"coreStrategy":"冠詞 a 後要接名詞，且要能「管理帳號」的必須是人；-ist 結尾的 specialist（專員）指人。","structure":"S: The company / V: is seeking / O: a specialist / 修飾語: to manage its social media accounts"},"source":"ORIGINAL"},
{"id":"p5-139","type":"context_vocabulary","sentence":"Before the new software is launched, it will be _____ tested to ensure there are no errors.","options":["hardly","barely","rarely","thoroughly"],"correctIndex":3,"explanation":{"coreStrategy":"目的是確保沒有錯誤（to ensure there are no errors），所以要「徹底地」測試，用 thoroughly。hardly、rarely、barely 都帶否定意味（幾乎不、很少），與確保無誤的目的矛盾。","structure":"S: it / V: will be tested / O: 無（被動語態）/ 修飾語: Before the new software is launched（副詞子句）；thoroughly；to ensure there are no errors（表目的）"},"source":"ORIGINAL"},
{"id":"p5-140","type":"connector","sentence":"_____ the rise in fuel prices, the airline has not increased its fares.","options":["Despite","Because","Because of","Although"],"correctIndex":0,"explanation":{"coreStrategy":"空格後是名詞片語 the rise in fuel prices，需要介系詞；油價上漲卻沒漲票價，是讓步關係，選 Despite。Because of 雖是介系詞，但表原因，語意相反；Although、Because 是連接詞，要接子句。","structure":"S: the airline / V: has not increased / O: its fares / 修飾語: Despite the rise in fuel prices"},"source":"ORIGINAL"},
{"id":"p5-141","type":"preposition_collocation","sentence":"The success of the project relies heavily _____ effective communication among team members.","options":["on","to","in","at"],"correctIndex":0,"explanation":{"coreStrategy":"rely on 表示「依賴」；副詞 heavily 插在中間不影響搭配。","structure":"S: The success of the project / V: relies on / O: effective communication / 修飾語: heavily；among team members"},"source":"ORIGINAL"},
{"id":"p5-142","type":"part_of_speech","sentence":"Mr. Brown's _____ was announced at the staff meeting yesterday.","options":["retire","retired","retiring","retirement"],"correctIndex":3,"explanation":{"coreStrategy":"所有格 Mr. Brown's 後要接名詞當主詞；-ment 結尾的 retirement 是名詞。","structure":"S: Mr. Brown's retirement / V: was announced / O: 無（被動語態）/ 修飾語: at the staff meeting；yesterday"},"source":"ORIGINAL"},
{"id":"p5-143","type":"context_vocabulary","sentence":"The renovation project was completed ahead of _____ and under budget.","options":["signature","survey","schedule","shelter"],"correctIndex":2,"explanation":{"coreStrategy":"ahead of schedule 意為「提前完成」，與 under budget（低於預算）並列，都是描述專案表現的固定說法。shelter（庇護所）、signature（簽名）、survey（調查）不能與 ahead of 搭配表示時程。","structure":"S: The renovation project / V: was completed / O: 無（被動語態）/ 修飾語: ahead of schedule and under budget"},"source":"ORIGINAL"},
{"id":"p5-144","type":"connector","sentence":"The seminar was canceled _____ too few people registered.","options":["because","therefore","in spite of","due to"],"correctIndex":0,"explanation":{"coreStrategy":"空格後是子句 too few people registered，需要連接詞；報名人數太少是取消的原因，選 because。due to、in spite of 是介系詞，不能接子句；therefore 是副詞，不能連接兩個子句，且因果方向相反。","structure":"S: The seminar / V: was canceled / O: 無（被動語態）/ 修飾語: because too few people registered（原因子句）"},"source":"ORIGINAL"},
{"id":"p5-145","type":"preposition_collocation","sentence":"Mr. Chen took part _____ the negotiations with the Singapore supplier.","options":["of","at","on","in"],"correctIndex":3,"explanation":{"coreStrategy":"take part in 表示「參與」，等於 participate in。","structure":"S: Mr. Chen / V: took part in / O: the negotiations / 修飾語: with the Singapore supplier"},"source":"ORIGINAL"},
{"id":"p5-146","type":"part_of_speech","sentence":"The instructions should be written _____ so that new staff can follow them easily.","options":["clear","clarity","clearly","clarify"],"correctIndex":2,"explanation":{"coreStrategy":"被動語態 should be written 已完整，空格修飾動作 written，需要副詞 clearly。","structure":"S: The instructions / V: should be written / O: 無（被動語態）/ 修飾語: clearly；so that new staff can follow them easily"},"source":"ORIGINAL"},
{"id":"p5-147","type":"context_vocabulary","sentence":"The bank's _____ hours are from 9 A.M. to 4 P.M. on weekdays.","options":["balance","business","burden","benefit"],"correctIndex":1,"explanation":{"coreStrategy":"business hours 意為「營業時間」，後面的 from 9 A.M. to 4 P.M. 是線索。balance（餘額）、benefit（福利）、burden（負擔）都不能和 hours 組成表示營業時段的名詞片語。","structure":"S: The bank's business hours / V: are / O: 無（補語 from 9 A.M. to 4 P.M.）/ 修飾語: on weekdays"},"source":"ORIGINAL"},
{"id":"p5-148","type":"connector","sentence":"_____ his lack of formal training, Mr. Okafor is one of the most skilled designers on our team.","options":["Although","Therefore","Because of","Notwithstanding"],"correctIndex":3,"explanation":{"coreStrategy":"空格後是名詞片語 his lack of formal training，需要介系詞；沒受過正式訓練卻是最優秀的設計師之一，是讓步關係，選 Notwithstanding（儘管），正式文書常用。Because of 表原因，語意相反；Although 是連接詞，要接子句；Therefore 是副詞，不能接名詞。","structure":"S: Mr. Okafor / V: is / O: 無（補語 one of the most skilled designers）/ 修飾語: Notwithstanding his lack of formal training；on our team"},"source":"ORIGINAL"},
{"id":"p5-149","type":"preposition_collocation","sentence":"Please consult _____ your supervisor before making any changes to the schedule.","options":["to","about","with","at"],"correctIndex":2,"explanation":{"coreStrategy":"consult with 人表示「與某人商量」；to、about、at 都不接在 consult 後面帶出商量對象。","structure":"S: （you，祈使句省略）/ V: Please consult with / O: your supervisor / 修飾語: before making any changes to the schedule"},"source":"ORIGINAL"},
{"id":"p5-150","type":"part_of_speech","sentence":"The warehouse staff worked _____ to meet the holiday shipping deadlines.","options":["tireless","tirelessness","tirelessly","tire"],"correctIndex":2,"explanation":{"coreStrategy":"空格修飾不及物動詞 worked，需要副詞；tirelessly 表示「不辭辛勞地」。","structure":"S: The warehouse staff / V: worked / O: 無（不及物動詞）/ 修飾語: tirelessly；to meet the holiday shipping deadlines"},"source":"ORIGINAL"},
{"id":"p5-151","type":"context_vocabulary","sentence":"Please _____ that all windows are closed before leaving the office.","options":["endure","ensure","enlarge","enroll"],"correctIndex":1,"explanation":{"coreStrategy":"空格後接 that 子句，表示「確保」窗戶都已關上，ensure that 是公告常見句型。enroll（註冊）、enlarge（擴大）、endure（忍受）都不接 that 子句。","structure":"S: （you，祈使句省略）/ V: Please ensure / O: that all windows are closed（名詞子句）/ 修飾語: before leaving the office"},"source":"ORIGINAL"},
{"id":"p5-152","type":"connector","sentence":"The company relocated its headquarters _____ the rent in the downtown area had become too high.","options":["because of","as","so","despite"],"correctIndex":1,"explanation":{"coreStrategy":"空格後是子句，需要連接詞；市中心租金太高是搬遷的原因，as 在此作「因為」解。despite、because of 是介系詞，不能接子句；so 表結果，因果方向顛倒。","structure":"S: The company / V: relocated / O: its headquarters / 修飾語: as the rent in the downtown area had become too high（原因子句）"},"source":"ORIGINAL"},
{"id":"p5-153","type":"preposition_collocation","sentence":"The airline is not liable _____ items left unattended in the terminal.","options":["to","of","with","for"],"correctIndex":3,"explanation":{"coreStrategy":"be liable for 表示「對……負（法律）責任」；be liable to 是「易於……」，後接原形動詞或疾病等，此處不合。","structure":"S: The airline / V: is not liable for / O: items / 修飾語: left unattended in the terminal（修飾 items）"},"source":"ORIGINAL"},
{"id":"p5-154","type":"part_of_speech","sentence":"Several _____ have been made to the original contract.","options":["revisions","revise","revised","revising"],"correctIndex":0,"explanation":{"coreStrategy":"Several 後接可數名詞複數當主詞，並搭配複數動詞 have been made；revisions 是名詞複數。","structure":"S: Several revisions / V: have been made / O: 無（被動語態）/ 修飾語: to the original contract"},"source":"ORIGINAL"},
{"id":"p5-155","type":"context_vocabulary","sentence":"The airline _____ passengers to arrive at the airport at least two hours before international flights.","options":["admits","advertises","advises","adopts"],"correctIndex":2,"explanation":{"coreStrategy":"advise + 人 + to V 意為「建議某人做某事」，航空公司建議旅客提早兩小時到機場。advertises（刊登廣告）、adopts（採用）、admits（承認、准許進入）都不用「人 + to V」表示建議。","structure":"S: The airline / V: advises / O: passengers / 修飾語: to arrive at the airport（受詞補語）；at least two hours before international flights"},"source":"ORIGINAL"},
{"id":"p5-156","type":"connector","sentence":"The bridge will be closed for repairs; _____, drivers should use the alternative route.","options":["although","despite","therefore","whereas"],"correctIndex":2,"explanation":{"coreStrategy":"分號後加逗號的位置需要連接副詞；橋梁封閉是因，改走替代道路是果，選 therefore。although、whereas 是連接詞，despite 是介系詞，都不能放在分號後加逗號的位置。","structure":"S: drivers / V: should use / O: the alternative route / 修飾語: therefore；（前一子句 The bridge will be closed for repairs）"},"source":"ORIGINAL"},
{"id":"p5-157","type":"preposition_collocation","sentence":"Increased demand has resulted _____ longer delivery times for some products.","options":["to","in","with","on"],"correctIndex":1,"explanation":{"coreStrategy":"A result in B 表示「A 導致 B」（原因在前、結果在後）；需求增加造成交期變長，選 in。","structure":"S: Increased demand / V: has resulted in / O: longer delivery times / 修飾語: for some products"},"source":"ORIGINAL"},
{"id":"p5-158","type":"part_of_speech","sentence":"The hotel staff were extremely _____ during our stay.","options":["helpful","help","helpfully","helpfulness"],"correctIndex":0,"explanation":{"coreStrategy":"be 動詞 were 後接形容詞補語，副詞 extremely 修飾形容詞；helpful 表示「樂於助人的」。","structure":"S: The hotel staff / V: were / O: 無（補語 extremely helpful）/ 修飾語: during our stay"},"source":"ORIGINAL"},
{"id":"p5-159","type":"context_vocabulary","sentence":"Thanks to its _____ location near the subway station, the hotel is popular with business travelers.","options":["consistent","convenient","contented","confident"],"correctIndex":1,"explanation":{"coreStrategy":"靠近地鐵站的位置「方便的」，是飯店受商務旅客歡迎的原因，convenient location 是常見搭配。confident（有自信的）、contented（滿足的）用來形容人；consistent（一致的）不能形容地點。","structure":"S: the hotel / V: is / O: 無（補語 popular）/ 修飾語: Thanks to its convenient location near the subway station；with business travelers"},"source":"ORIGINAL"},
{"id":"p5-160","type":"connector","sentence":"_____ the store offered large discounts, sales remained lower than expected.","options":["Due to","Even though","Because","In spite of"],"correctIndex":1,"explanation":{"coreStrategy":"空格後是子句，需要連接詞；大打折扣但銷售仍不如預期，是讓步關係，選 Even though。Because 表原因，語意相反；Due to、In spite of 是介系詞，不能接子句。","structure":"S: sales / V: remained / O: 無（補語 lower than expected）/ 修飾語: Even though the store offered large discounts（讓步子句）"},"source":"ORIGINAL"},
{"id":"p5-161","type":"preposition_collocation","sentence":"The workshop is intended _____ managers who supervise five or more employees.","options":["for","to","at","of"],"correctIndex":0,"explanation":{"coreStrategy":"be intended for + 對象，表示「專為……而設計」；intended to 後面接原形動詞。","structure":"S: The workshop / V: is intended for / O: managers / 修飾語: who supervise five or more employees（關係子句）"},"source":"ORIGINAL"},
{"id":"p5-162","type":"part_of_speech","sentence":"This year's conference will focus on _____ business practices.","options":["sustainably","sustain","sustains","sustainable"],"correctIndex":3,"explanation":{"coreStrategy":"介系詞 on 後接名詞片語 business practices，空格修飾名詞，需要形容詞 sustainable（永續的）。","structure":"S: This year's conference / V: will focus on / O: sustainable business practices / 修飾語: 無"},"source":"ORIGINAL"},
{"id":"p5-163","type":"context_vocabulary","sentence":"The finance department is _____ the budget for next year and will finalize it by May.","options":["reviewing","reviving","rewarding","revoking"],"correctIndex":0,"explanation":{"coreStrategy":"後半句說五月前定案（finalize），所以現在正在「審查」預算，用 reviewing。reviving（使復甦）、revoking（撤銷）、rewarding（獎勵）都不是定案前的步驟。","structure":"S: The finance department / V: is reviewing / O: the budget / 修飾語: for next year；and will finalize it by May（對等動詞片語）"},"source":"ORIGINAL"},
{"id":"p5-164","type":"connector","sentence":"The new branch opened ahead of schedule _____ the hard work of the construction crew.","options":["although","despite","thanks to","whereas"],"correctIndex":2,"explanation":{"coreStrategy":"空格後是名詞片語 the hard work，需要介系詞；施工團隊的努力是提前開幕的原因，選 thanks to（多虧）。despite 表讓步，語意相反；although、whereas 是連接詞，要接子句。","structure":"S: The new branch / V: opened / O: 無（不及物動詞）/ 修飾語: ahead of schedule；thanks to the hard work of the construction crew"},"source":"ORIGINAL"},
{"id":"p5-165","type":"preposition_collocation","sentence":"Ms. Okafor has a strong background _____ financial analysis.","options":["on","of","in","at"],"correctIndex":2,"explanation":{"coreStrategy":"background in + 領域，表示「在某領域的學經歷背景」。","structure":"S: Ms. Okafor / V: has / O: a strong background / 修飾語: in financial analysis"},"source":"ORIGINAL"},
{"id":"p5-166","type":"part_of_speech","sentence":"The finance department has _____ reduced unnecessary spending.","options":["successful","successfully","success","succeed"],"correctIndex":1,"explanation":{"coreStrategy":"空格位於 has 與過去分詞 reduced 之間，只能放副詞 successfully。","structure":"S: The finance department / V: has reduced / O: unnecessary spending / 修飾語: successfully"},"source":"ORIGINAL"},
{"id":"p5-167","type":"context_vocabulary","sentence":"Each new intern will be _____ a mentor who will guide them through their first month.","options":["assigned","assumed","assembled","associated"],"correctIndex":0,"explanation":{"coreStrategy":"be assigned + 人 意為「被分派到（某人）」，每位實習生被分配一位導師，是雙受詞動詞 assign 的被動用法。assembled（組裝）、assumed（假定）、associated（聯想）都不是雙受詞動詞，被動後不能再接 a mentor。","structure":"S: Each new intern / V: will be assigned / O: a mentor（保留受詞）/ 修飾語: who will guide them through their first month（關係子句）"},"source":"ORIGINAL"},
{"id":"p5-168","type":"connector","sentence":"Mr. Gomez speaks three languages fluently; _____, he is often asked to assist international clients.","options":["although","hence","however","despite"],"correctIndex":1,"explanation":{"coreStrategy":"分號後加逗號的位置需要連接副詞；會說三種語言是因，常被請去協助國際客戶是果，選 hence（因此）。however 表轉折，語意不通；although 是連接詞、despite 是介系詞，不能放在此處。","structure":"S: he / V: is often asked / O: 無（被動語態）/ 修飾語: hence；to assist international clients；（前一子句 Mr. Gomez speaks three languages fluently）"},"source":"ORIGINAL"},
{"id":"p5-169","type":"preposition_collocation","sentence":"The quarterly report must be submitted _____ the finance department no later than Thursday.","options":["to","at","of","on"],"correctIndex":0,"explanation":{"coreStrategy":"submit A to B 表示「把 A 提交給 B」；被動 A be submitted to B。","structure":"S: The quarterly report / V: must be submitted to / O: the finance department / 修飾語: no later than Thursday"},"source":"ORIGINAL"},
{"id":"p5-170","type":"part_of_speech","sentence":"Ms. Wong gave a _____ explanation of the new billing system.","options":["detail","details","detailed","detailing"],"correctIndex":2,"explanation":{"coreStrategy":"冠詞 a 與名詞 explanation 之間要放形容詞；過去分詞 detailed 當形容詞，表示「詳細的」。","structure":"S: Ms. Wong / V: gave / O: a detailed explanation / 修飾語: of the new billing system"},"source":"ORIGINAL"},
{"id":"p5-171","type":"context_vocabulary","sentence":"The company's profits _____ last quarter, so executives are looking for ways to cut costs.","options":["declined","designed","declared","described"],"correctIndex":0,"explanation":{"coreStrategy":"so 之後的結果是高層想辦法削減成本，可推知利潤「下滑」，用 declined（不及物）。declared（宣布）、designed（設計）、described（描述）都是及物動詞，後面缺受詞，語意也不通。","structure":"S: The company's profits / V: declined / O: 無（不及物動詞）/ 修飾語: last quarter；so executives are looking for ways to cut costs（對等子句）"},"source":"ORIGINAL"},
{"id":"p5-172","type":"connector","sentence":"The meeting ran late, _____ several participants had to leave before the final presentation.","options":["because of","although","despite","so"],"correctIndex":3,"explanation":{"coreStrategy":"逗號後是子句，表示前句的結果（會議延長，所以有人提早離開），選對等連接詞 so。although 表讓步，語意不通；because of、despite 是介系詞，不能接子句。","structure":"S: The meeting / V: ran / O: 無（不及物動詞）/ 修飾語: late；so several participants had to leave before the final presentation（對等子句）"},"source":"ORIGINAL"},
{"id":"p5-173","type":"preposition_collocation","sentence":"The board is still deciding _____ the two candidates for the vice president position.","options":["among","from","between","with"],"correctIndex":2,"explanation":{"coreStrategy":"decide between A and B（兩者之間做決定）；空格後是 the two candidates，兩者用 between，三者以上才用 among。","structure":"S: The board / V: is deciding between / O: the two candidates / 修飾語: still；for the vice president position"},"source":"ORIGINAL"},
{"id":"p5-174","type":"part_of_speech","sentence":"The company plans to hire _____ staff to handle the busy season.","options":["additional","addition","additionally","add"],"correctIndex":0,"explanation":{"coreStrategy":"空格在名詞 staff 前，作為 hire 的受詞的一部分，需要形容詞 additional（額外的）。","structure":"S: The company / V: plans / O: to hire additional staff / 修飾語: to handle the busy season"},"source":"ORIGINAL"},
{"id":"p5-175","type":"context_vocabulary","sentence":"Due to _____ weather conditions, all outdoor activities have been canceled.","options":["sincere","several","secure","severe"],"correctIndex":3,"explanation":{"coreStrategy":"所有戶外活動被取消，原因是天候「惡劣、嚴峻」，severe weather 是固定搭配。several（幾個的）、sincere（真誠的）、secure（安全的）都不能說明取消的原因。","structure":"S: all outdoor activities / V: have been canceled / O: 無（被動語態）/ 修飾語: Due to severe weather conditions"},"source":"ORIGINAL"},
{"id":"p5-176","type":"connector","sentence":"_____ being one of the smallest firms in the industry, Rayburn Tech has won several major contracts.","options":["Because","However","Therefore","Despite"],"correctIndex":3,"explanation":{"coreStrategy":"空格後是動名詞片語 being one of the smallest firms，需要介系詞；公司規模小卻拿下大合約，是讓步關係，選 Despite。Because 是連接詞，不能直接接動名詞；However、Therefore 是副詞，不能接動名詞片語。","structure":"S: Rayburn Tech / V: has won / O: several major contracts / 修飾語: Despite being one of the smallest firms in the industry"},"source":"ORIGINAL"},
{"id":"p5-177","type":"preposition_collocation","sentence":"Thanks to the new system, staff can now gain access _____ client files from any location.","options":["to","for","of","at"],"correctIndex":0,"explanation":{"coreStrategy":"access to 表示「取得……的管道、存取權」；gain／have access to 是固定搭配。","structure":"S: staff / V: can gain / O: access to client files / 修飾語: Thanks to the new system；now；from any location"},"source":"ORIGINAL"},
{"id":"p5-178","type":"part_of_speech","sentence":"The director was _____ impressed with the quality of the proposal.","options":["deep","depth","deeply","deepen"],"correctIndex":2,"explanation":{"coreStrategy":"空格修飾形容詞（過去分詞）impressed，需要副詞 deeply。","structure":"S: The director / V: was impressed / O: 無（補語 deeply impressed）/ 修飾語: with the quality of the proposal"},"source":"ORIGINAL"},
{"id":"p5-179","type":"context_vocabulary","sentence":"The orientation will _____ an overview of company policies and a tour of the facility.","options":["include","conclude","preclude","exclude"],"correctIndex":0,"explanation":{"coreStrategy":"新人說明會的內容「包含」政策介紹與設施導覽，include 後接所含項目。conclude（結束）、exclude（排除）、preclude（妨礙）都與說明會提供這些內容的語意不符。","structure":"S: The orientation / V: will include / O: an overview of company policies and a tour of the facility / 修飾語: 無"},"source":"ORIGINAL"},
{"id":"p5-180","type":"connector","sentence":"The package could not be delivered _____ the address on the label was incorrect.","options":["because","because of","so that","although"],"correctIndex":0,"explanation":{"coreStrategy":"空格後是子句 the address was incorrect，需要連接詞；地址錯誤是無法投遞的原因，選 because。although 表讓步、so that 表目的，語意都不通；because of 是介系詞，不能接子句。","structure":"S: The package / V: could not be delivered / O: 無（被動語態）/ 修飾語: because the address on the label was incorrect（原因子句）"},"source":"ORIGINAL"},
{"id":"p5-181","type":"preposition_collocation","sentence":"The research team is currently focusing _____ ways to reduce packaging waste.","options":["at","in","on","to"],"correctIndex":2,"explanation":{"coreStrategy":"focus on 表示「專注於」。","structure":"S: The research team / V: is focusing on / O: ways / 修飾語: currently；to reduce packaging waste（修飾 ways）"},"source":"ORIGINAL"},
{"id":"p5-182","type":"part_of_speech","sentence":"Our goal is to provide high-quality products at _____ prices.","options":["affordable","afford","affordably","affordability"],"correctIndex":0,"explanation":{"coreStrategy":"空格在名詞 prices 前，需要形容詞；-able 結尾的 affordable 表示「負擔得起的」。","structure":"S: Our goal / V: is / O: 無（補語 to provide high-quality products）/ 修飾語: at affordable prices"},"source":"ORIGINAL"},
{"id":"p5-183","type":"context_vocabulary","sentence":"Mr. Lopez submitted his _____ last week because he accepted a position at another firm.","options":["reservation","registration","recommendation","resignation"],"correctIndex":3,"explanation":{"coreStrategy":"because 子句說明他接受了別家公司的職位，所以他提交的是「辭呈」，submit one's resignation 是固定說法。reservation（預約）、registration（登記）、recommendation（推薦）都與跳槽沒有因果關係。","structure":"S: Mr. Lopez / V: submitted / O: his resignation / 修飾語: last week；because he accepted a position at another firm（副詞子句）"},"source":"ORIGINAL"},
{"id":"p5-184","type":"connector","sentence":"The training session was very informative, _____ it was a little too long.","options":["although","despite","due to","because"],"correctIndex":0,"explanation":{"coreStrategy":"逗號後是子句 it was a little too long，需要連接詞；內容豐富但太長，是讓步關係，選 although。because 表原因，語意不通；despite、due to 是介系詞，不能接子句。","structure":"S: The training session / V: was / O: 無（補語 very informative）/ 修飾語: although it was a little too long（讓步子句）"},"source":"ORIGINAL"},
{"id":"p5-185","type":"preposition_collocation","sentence":"Each department head is required to keep track _____ overtime hours worked by staff.","options":["of","on","with","for"],"correctIndex":0,"explanation":{"coreStrategy":"keep track of 表示「追蹤、記錄」，是固定片語。","structure":"S: Each department head / V: is required / O: to keep track of overtime hours / 修飾語: worked by staff（修飾 hours）"},"source":"ORIGINAL"},
{"id":"p5-186","type":"part_of_speech","sentence":"The new assembly line has improved _____ by twenty percent.","options":["productive","productively","producing","productivity"],"correctIndex":3,"explanation":{"coreStrategy":"及物動詞 improved 後面需要名詞當受詞；-ity 結尾的 productivity 表示「生產力」。","structure":"S: The new assembly line / V: has improved / O: productivity / 修飾語: by twenty percent"},"source":"ORIGINAL"},
{"id":"p5-187","type":"context_vocabulary","sentence":"The landlord agreed to _____ the lease for another two years.","options":["renew","reveal","remind","repair"],"correctIndex":0,"explanation":{"coreStrategy":"for another two years（再兩年）是線索，房東同意「續簽」租約，renew a lease 是固定搭配。reveal（揭露）、remind（提醒）、repair（修理）都不能以租約為受詞並延長期限。","structure":"S: The landlord / V: agreed / O: to renew the lease / 修飾語: for another two years"},"source":"ORIGINAL"},
{"id":"p5-188","type":"connector","sentence":"_____ the economic slowdown, the company managed to increase its market share.","options":["Owing to","Therefore","In spite of","Although"],"correctIndex":2,"explanation":{"coreStrategy":"空格後是名詞片語 the economic slowdown，需要介系詞；景氣放緩卻仍擴大市占率，是讓步關係，選 In spite of。Owing to 表原因，語意相反；Although 是連接詞，要接子句；Therefore 是副詞，不能接名詞。","structure":"S: the company / V: managed / O: to increase its market share / 修飾語: In spite of the economic slowdown"},"source":"ORIGINAL"},
{"id":"p5-189","type":"preposition_collocation","sentence":"The proposed merger is still pending approval _____ government regulators.","options":["to","at","on","from"],"correctIndex":3,"explanation":{"coreStrategy":"approval from + 核准者，表示「來自……的核准」；空格後是核准的機關 government regulators。","structure":"S: The proposed merger / V: is pending / O: approval / 修飾語: still；from government regulators"},"source":"ORIGINAL"},
{"id":"p5-190","type":"part_of_speech","sentence":"The seminar was _____ organized, and participants praised its clear schedule.","options":["efficient","efficiency","efficiencies","efficiently"],"correctIndex":3,"explanation":{"coreStrategy":"空格位於 was 與過去分詞 organized 之間，修飾動作，需要副詞 efficiently。","structure":"S: The seminar / V: was organized / O: 無（被動語態）/ 修飾語: efficiently；（後一子句 participants praised its clear schedule）"},"source":"ORIGINAL"},
{"id":"p5-191","type":"context_vocabulary","sentence":"Customer _____ has improved significantly since we introduced the new online support system.","options":["saturation","satisfaction","sanitation","salutation"],"correctIndex":1,"explanation":{"coreStrategy":"導入新的線上客服系統後，「顧客滿意度」明顯提升，customer satisfaction 是常見複合名詞。saturation（飽和）、sanitation（公共衛生）、salutation（問候語）拼字相近，語意不通。","structure":"S: Customer satisfaction / V: has improved / O: 無（不及物動詞）/ 修飾語: significantly；since we introduced the new online support system（副詞子句）"},"source":"ORIGINAL"},
{"id":"p5-192","type":"connector","sentence":"The marketing campaign was a great success. _____, the company plans to run a similar one next year.","options":["Even though","In spite of","As a result","Nevertheless"],"correctIndex":2,"explanation":{"coreStrategy":"新句子開頭加逗號，需要連接副詞片語；活動大成功是因，明年再辦是果，選 As a result。Nevertheless 表讓步，語意不通；Even though 是連接詞，In spite of 是介系詞，後面都不能直接加逗號再接子句。","structure":"S: the company / V: plans / O: to run a similar one / 修飾語: As a result；next year；（前一句 The marketing campaign was a great success）"},"source":"ORIGINAL"},
{"id":"p5-193","type":"preposition_collocation","sentence":"The new branch office will be similar _____ the one we opened in Taipei last year.","options":["with","as","to","for"],"correctIndex":2,"explanation":{"coreStrategy":"be similar to 表示「與……相似」；不可用 with 或 as（as 用於 the same as）。","structure":"S: The new branch office / V: will be similar to / O: the one / 修飾語: (that) we opened in Taipei last year（關係子句）"},"source":"ORIGINAL"},
{"id":"p5-194","type":"part_of_speech","sentence":"The manager asked the team to _____ the sales data before the meeting.","options":["analysis","analytical","analyze","analytically"],"correctIndex":2,"explanation":{"coreStrategy":"不定詞 to 後面接原形動詞；analyze 是動詞，後面接受詞 the sales data。","structure":"S: The manager / V: asked / O: the team / 修飾語: to analyze the sales data（受詞補語）；before the meeting"},"source":"ORIGINAL"},
{"id":"p5-195","type":"context_vocabulary","sentence":"The new printer is more _____ than the old one, using 30 percent less electricity.","options":["proficient","efficient","deficient","sufficient"],"correctIndex":1,"explanation":{"coreStrategy":"分詞片語 using 30 percent less electricity（少用三成電力）說明新印表機更「有效率、節能」，用 efficient。sufficient（足夠的）不用比較級；proficient（精通的）形容人；deficient（不足的）與省電語意相反。","structure":"S: The new printer / V: is / O: 無（補語 more efficient）/ 修飾語: than the old one；using 30 percent less electricity（分詞片語）"},"source":"ORIGINAL"},
{"id":"p5-196","type":"connector","sentence":"_____ the price of raw materials has risen, the manufacturer has decided to raise the price of its products.","options":["Whereas","Since","Despite","Although"],"correctIndex":1,"explanation":{"coreStrategy":"空格後是子句，需要連接詞；原料漲價是產品漲價的原因，since 在此作「因為」解。Although、Whereas 表讓步或對比，語意不通；Despite 是介系詞，不能接子句。","structure":"S: the manufacturer / V: has decided / O: to raise the price of its products / 修飾語: Since the price of raw materials has risen（原因子句）"},"source":"ORIGINAL"},
{"id":"p5-197","type":"preposition_collocation","sentence":"Mr. Dubois succeeded _____ securing a long-term contract with the city government.","options":["on","for","in","to"],"correctIndex":2,"explanation":{"coreStrategy":"succeed in + V-ing 表示「成功做到」；succeed to 是「繼承（職位）」，意思不同。","structure":"S: Mr. Dubois / V: succeeded in / O: securing a long-term contract / 修飾語: with the city government"},"source":"ORIGINAL"},
{"id":"p5-198","type":"part_of_speech","sentence":"Due to _____ demand, the store will extend its holiday hours.","options":["overwhelm","overwhelmingly","overwhelms","overwhelming"],"correctIndex":3,"explanation":{"coreStrategy":"介系詞片語 Due to 後接名詞片語，空格修飾名詞 demand，需要形容詞；現在分詞 overwhelming 當形容詞，表示「壓倒性的、極大的」。","structure":"S: the store / V: will extend / O: its holiday hours / 修飾語: Due to overwhelming demand"},"source":"ORIGINAL"},
{"id":"p5-199","type":"context_vocabulary","sentence":"Staff members are _____ to submit their expense reports by the fifth of each month.","options":["inquired","retired","required","acquired"],"correctIndex":2,"explanation":{"coreStrategy":"be required to V 意為「被要求、必須做某事」，是公司規定的常見句型。acquired（取得）、inquired（詢問）、retired（退休）都不能接 to V 表示規定。","structure":"S: Staff members / V: are required / O: 無（被動語態）/ 修飾語: to submit their expense reports；by the fifth of each month"},"source":"ORIGINAL"},
{"id":"p5-200","type":"connector","sentence":"Customer complaints have decreased significantly _____ the introduction of a 24-hour help line.","options":["in spite of","even though","therefore","as a result of"],"correctIndex":3,"explanation":{"coreStrategy":"空格後是名詞片語 the introduction of a 24-hour help line，需要介系詞；設立 24 小時客服專線是客訴減少的原因，選 as a result of（由於）。in spite of 表讓步，語意相反；even though 是連接詞，要接子句；therefore 是副詞，不能接名詞。","structure":"S: Customer complaints / V: have decreased / O: 無（不及物動詞）/ 修飾語: significantly；as a result of the introduction of a 24-hour help line"},"source":"ORIGINAL"}
];
